window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[14]={"1400":{"example:1400:exzh":"He is an excellent student.","example:1400:exzh2":"I think this work is excellent.","example:1400:exzh3":"We are looking for excellent people.","example:1400:exzh4":"I got excellent results.","example:1400:exzh5":"She is an excellent leader."},"1401":{"example:1401:exzh":"I'm waiting for the final decision.","example:1401:exzh2":"The final results will be announced next week.","example:1401:exzh3":"That is the ultimate goal.","example:1401:exzh4":"I caught the last train.","example:1401:exzh5":"In the end, everything went well."},"1402":{"example:1402:exzh":"There are five photos here.","example:1402:exzh2":"I bought two tickets.","example:1402:exzh3":"I found one coin.","example:1402:exzh4":"He has three stickers.","example:1402:exzh5":"Five sheets of paper are needed.","grammar:1402:ex:trans":"There are five photos here.","grammar:1402:ex:structure":"〜枚の〜があります","grammar:1402:ex:explain":"This is the most typical existential sentence, 「〜に〜があります」. In 「ここに」 the 「に」 marks the place where something exists, and the sentence-final 「あります」 expresses the existence of inanimate things such as photos; for people or animals you would use 「います」 instead. The counter 「枚（まい）」 counts thin, flat things such as photos, sheets of paper, plates, and CDs, and 「五枚」 is read 「ごまい」. Note that Japanese usually puts the number before the noun: 「五枚の写真」 means five photos, with 「の」 linking the number to the noun.","grammar:1402:ex:words:0:zh":"here","grammar:1402:ex:words:0:pos":"pronoun","grammar:1402:ex:words:1:zh":"(location of existence)","grammar:1402:ex:words:1:pos":"particle","grammar:1402:ex:words:2:zh":"five","grammar:1402:ex:words:2:note":"ごまい","grammar:1402:ex:words:2:pos":"noun","grammar:1402:ex:words:3:zh":"'s","grammar:1402:ex:words:3:pos":"particle","grammar:1402:ex:words:4:zh":"photo","grammar:1402:ex:words:4:note":"しゃしん","grammar:1402:ex:words:4:pos":"noun","grammar:1402:ex:words:5:zh":"(nominative)","grammar:1402:ex:words:5:pos":"particle","grammar:1402:ex:words:6:zh":"there is / are","grammar:1402:ex:words:6:pos":"verb","grammar:1402:ex:points:0":"❗〜枚（まい）: counter for thin, flat things; 五枚 = ごまい.","grammar:1402:ex:points:1":"五枚の写真: five photos.","grammar:1402:ex2:trans":"I bought two tickets.","grammar:1402:ex2:structure":"〜枚の〜を買いました","grammar:1402:ex2:words:0:zh":"two","grammar:1402:ex2:words:0:note":"にまい","grammar:1402:ex2:words:0:pos":"noun","grammar:1402:ex2:words:1:zh":"'s","grammar:1402:ex2:words:1:pos":"particle","grammar:1402:ex2:words:2:zh":"tickets","grammar:1402:ex2:words:2:note":"きっぷ","grammar:1402:ex2:words:2:pos":"noun","grammar:1402:ex2:words:3:zh":"(object marker)","grammar:1402:ex2:words:3:pos":"particle","grammar:1402:ex2:words:4:zh":"bought","grammar:1402:ex2:words:4:note":"かいました","grammar:1402:ex2:words:4:pos":"verb","grammar:1402:ex2:points:0":"❗二枚: two (にまい); 切符 = a ticket.","grammar:1402:ex2:points:1":"二枚の切符: two tickets.","grammar:1402:ex3:trans":"I found one coin.","grammar:1402:ex3:structure":"〜枚の〜を見つけました","grammar:1402:ex3:words:0:zh":"one","grammar:1402:ex3:words:0:note":"いちまい","grammar:1402:ex3:words:0:pos":"noun","grammar:1402:ex3:words:1:zh":"'s","grammar:1402:ex3:words:1:pos":"particle","grammar:1402:ex3:words:2:zh":"a coin","grammar:1402:ex3:words:2:note":"loanword","grammar:1402:ex3:words:2:pos":"noun","grammar:1402:ex3:words:3:zh":"(object marker)","grammar:1402:ex3:words:3:pos":"particle","grammar:1402:ex3:words:4:zh":"found","grammar:1402:ex3:words:4:note":"みつけました","grammar:1402:ex3:words:4:pos":"verb","grammar:1402:ex3:points:0":"❗一枚: one (いちまい); コイン = a coin.","grammar:1402:ex3:points:1":"一枚のコイン: one coin.","grammar:1402:ex4:trans":"He has three stickers.","grammar:1402:ex4:structure":"〜枚の〜を持っています","grammar:1402:ex4:words:0:zh":"he","grammar:1402:ex4:words:0:note":"かれ","grammar:1402:ex4:words:0:pos":"pronoun","grammar:1402:ex4:words:1:zh":"(topic)","grammar:1402:ex4:words:1:pos":"particle","grammar:1402:ex4:words:2:zh":"three","grammar:1402:ex4:words:2:note":"さんまい","grammar:1402:ex4:words:2:pos":"noun","grammar:1402:ex4:words:3:zh":"'s","grammar:1402:ex4:words:3:pos":"particle","grammar:1402:ex4:words:4:zh":"stickers","grammar:1402:ex4:words:4:note":"loanword","grammar:1402:ex4:words:4:pos":"noun","grammar:1402:ex4:words:5:zh":"(object marker)","grammar:1402:ex4:words:5:pos":"particle","grammar:1402:ex4:words:6:zh":"own, have","grammar:1402:ex4:words:6:note":"もっています","grammar:1402:ex4:words:6:pos":"verb","grammar:1402:ex4:points:0":"❗三枚: three (さんまい); シール = a sticker.","grammar:1402:ex4:points:1":"三枚のシール: three stickers.","grammar:1402:ex5:trans":"Five sheets of paper are needed.","grammar:1402:ex5:structure":"〜枚の〜が必要です","grammar:1402:ex5:words:0:zh":"five","grammar:1402:ex5:words:0:note":"ごまい","grammar:1402:ex5:words:0:pos":"noun","grammar:1402:ex5:words:1:zh":"'s","grammar:1402:ex5:words:1:pos":"particle","grammar:1402:ex5:words:2:zh":"paper","grammar:1402:ex5:words:2:note":"かみ","grammar:1402:ex5:words:2:pos":"noun","grammar:1402:ex5:words:3:zh":"(nominative)","grammar:1402:ex5:words:3:pos":"particle","grammar:1402:ex5:words:4:zh":"necessary","grammar:1402:ex5:words:4:note":"ひつよう","grammar:1402:ex5:words:4:pos":"na-adjective","grammar:1402:ex5:words:5:zh":"(polite form)","grammar:1402:ex5:words:5:pos":"copula","grammar:1402:ex5:points:0":"❗五枚の紙: five sheets of paper; 紙 = paper.","grammar:1402:ex5:points:1":"紙が必要: paper is needed.","exam:1402:zh":"Please give me one sheet of paper so I can write my name.","exam:1402:why":"Paper is a thin, flat item, counted with 「枚」. 「冊」 counts bound items like books and isn't used for single sheets of paper."},"1403":{"example:1403:exzh":"The United States is a federal state.","example:1403:exzh2":"The federal government enacted a new law.","example:1403:exzh3":"Taking part as a member of the federation.","example:1403:exzh4":"Cooperation within the federation is important.","example:1403:exzh5":"This issue is connected to the federation."},"1404":{"example:1404:exzh":"He has versatile talent.","example:1404:exzh2":"I'm looking for a job where I can make use of my talent.","example:1404:exzh3":"She has wonderful talent.","example:1404:exzh4":"I will practice in order to develop my talent.","example:1404:exzh5":"If you have talent, you can succeed."},"1405":{"example:1405:exzh":"This is the maximum value.","example:1405:exzh2":"He has the greatest goal.","example:1405:exzh3":"This machine can withstand the maximum load.","example:1405:exzh4":"I will pursue the greatest results.","example:1405:exzh5":"I will make the greatest effort in order to succeed."},"1406":{"example:1406:exzh":"He moved the car.","example:1406:exzh2":"I can't move this heavy box.","example:1406:exzh3":"I'm pushing that plan forward.","example:1406:exzh4":"Please be careful when moving it.","example:1406:exzh5":"She is moving her arm."},"1407":{"example:1407:exzh":"This job has several conditions.","example:1407:exzh2":"You must meet the conditions.","example:1407:exzh3":"He presented the conditions.","example:1407:exzh4":"This contract has special conditions.","example:1407:exzh5":"Let's discuss the conditions."},"1408":{"example:1408:exzh":"His charm is obvious at a glance.","example:1408:exzh2":"That movie had a fascinating story.","example:1408:exzh3":"Learn how to bring out your charm.","example:1408:exzh4":"There is no one who doesn't notice her charm.","example:1408:exzh5":"I'm drawn to this brand's charm."},"1409":{"example:1409:exzh":"Earth is a blue planet.","example:1409:exzh2":"Jupiter is the largest planet.","example:1409:exzh3":"A new planet was discovered recently.","example:1409:exzh4":"I study how the planets move.","example:1409:exzh5":"All planets revolve around the sun."},"1410":{"example:1410:exzh":"Violence is never the solution.","example:1410:exzh2":"The violence shown in movies isn't real.","example:1410:exzh3":"Laws against violence are needed.","example:1410:exzh4":"He should stop violent behavior.","example:1410:exzh5":"Violence is part of social problems."},"1411":{"example:1411:exzh":"A small bell rang in the wind.","example:1411:exzh2":"She has a bell.","example:1411:exzh3":"The sound of the bell is soothing.","example:1411:exzh4":"I put a bell on the cat's collar.","example:1411:exzh5":"He rang the bell."},"1412":{"example:1412:exzh":"It's wrong to blame her.","example:1412:exzh2":"It's not good to blame yourself.","example:1412:exzh3":"He didn't blame his friend.","example:1412:exzh4":"No one has the right to blame.","example:1412:exzh5":"Blaming each other is pointless."},"1413":{"example:1413:exzh":"She has a beautiful ring.","example:1413:exzh2":"I'm planning to buy a ring.","example:1413:exzh3":"That ring is very expensive.","example:1413:exzh4":"Giving a ring has a special meaning.","example:1413:exzh5":"I'm looking for a wedding ring."},"1415":{"example:1415:exzh":"They entered combat.","example:1415:exzh2":"Combat is extremely dangerous.","example:1415:exzh3":"Combat is important in this game.","example:1415:exzh4":"You should stay calm in combat.","example:1415:exzh5":"He is a combat expert."},"1416":{"example:1416:exzh":"This school is popular.","example:1416:exzh2":"There are many schools in tea ceremony.","example:1416:exzh3":"A new school is developing.","example:1416:exzh4":"Be careful that the school doesn't die out.","example:1416:exzh5":"He changed his musical style."},"1417":{"example:1417:exzh":"The effects of this medicine appear quickly.","example:1417:exzh2":"I'm looking for an effective method.","example:1417:exzh3":"We did a test to confirm the effect.","example:1417:exzh4":"This supplement has many benefits.","example:1417:exzh5":"His effort had a big effect."},"1418":{"example:1418:exzh":"He has grown up.","example:1418:exzh2":"Adults should protect children.","example:1418:exzh3":"Please listen to adults' opinions.","example:1418:exzh4":"Today there's a gathering for adults only.","example:1418:exzh5":"Adults must take responsibility.","grammar:1418:ex:trans":"He has grown up.","grammar:1418:ex:structure":"〜になりました","grammar:1418:ex:explain":"The core of this sentence is the change pattern 「〜になる」, meaning to become or turn into a certain state. The noun 「大人」 takes 「に」 and then 「なる」, so 「大人になる」 means to grow up and become an adult. This 「に」 marks the result of the change. 「なりました」 is the polite past form of 「なる」, showing a change that is already complete. The whole sentence 「彼は大人になりました」 means he has grown up; 「は」 marks the topic and the tone states a fact.","grammar:1418:ex:words:0:zh":"he","grammar:1418:ex:words:0:note":"かれ","grammar:1418:ex:words:0:pos":"pronoun","grammar:1418:ex:words:1:zh":"(topic)","grammar:1418:ex:words:1:pos":"particle","grammar:1418:ex:words:2:zh":"adult","grammar:1418:ex:words:2:note":"おとな","grammar:1418:ex:words:2:pos":"noun","grammar:1418:ex:words:3:zh":"(result)","grammar:1418:ex:words:3:pos":"particle","grammar:1418:ex:words:4:zh":"became","grammar:1418:ex:words:4:pos":"verb","grammar:1418:ex:points:0":"❗大人（おとな）: adult, grown-up; 〜になる = to become… (大人になる = to grow up).","grammar:1418:ex:points:1":"大人になる: to become an adult.","grammar:1418:ex2:trans":"Adults should protect children.","grammar:1418:ex2:structure":"〜を守るべきです","grammar:1418:ex2:words:0:zh":"adult","grammar:1418:ex2:words:0:note":"おとな","grammar:1418:ex2:words:0:pos":"noun","grammar:1418:ex2:words:1:zh":"(topic)","grammar:1418:ex2:words:1:pos":"particle","grammar:1418:ex2:words:2:zh":"child","grammar:1418:ex2:words:2:note":"こども","grammar:1418:ex2:words:2:pos":"noun","grammar:1418:ex2:words:3:zh":"(object marker)","grammar:1418:ex2:words:3:pos":"particle","grammar:1418:ex2:words:4:zh":"protect","grammar:1418:ex2:words:4:note":"まもる","grammar:1418:ex2:words:4:pos":"verb","grammar:1418:ex2:words:5:zh":"should","grammar:1418:ex2:words:5:pos":"particle","grammar:1418:ex2:words:6:zh":"(polite form)","grammar:1418:ex2:words:6:pos":"copula","grammar:1418:ex2:points:0":"❗〜べきです: should…; 子供を守る = to protect children.","grammar:1418:ex2:points:1":"守るべき: should protect.","grammar:1418:ex3:trans":"Please listen to the adults' opinions.","grammar:1418:ex3:structure":"〜の意見を聞いてください","grammar:1418:ex3:words:0:zh":"adult","grammar:1418:ex3:words:0:note":"おとな","grammar:1418:ex3:words:0:pos":"noun","grammar:1418:ex3:words:1:zh":"'s","grammar:1418:ex3:words:1:pos":"particle","grammar:1418:ex3:words:2:zh":"opinion","grammar:1418:ex3:words:2:note":"いけん","grammar:1418:ex3:words:2:pos":"noun","grammar:1418:ex3:words:3:zh":"(object marker)","grammar:1418:ex3:words:3:pos":"particle","grammar:1418:ex3:words:4:zh":"listen","grammar:1418:ex3:words:4:note":"きいて","grammar:1418:ex3:words:4:pos":"verb","grammar:1418:ex3:words:5:zh":"please","grammar:1418:ex3:words:5:pos":"auxiliary verb","grammar:1418:ex3:points:0":"大人の意見: the opinion of an adult.","grammar:1418:ex3:points:1":"意見を聞く: to listen to an opinion.","grammar:1418:ex4:trans":"Today there's a gathering for adults only.","grammar:1418:ex4:structure":"〜だけの〜があります","grammar:1418:ex4:words:0:zh":"today","grammar:1418:ex4:words:0:note":"きょう","grammar:1418:ex4:words:0:pos":"noun","grammar:1418:ex4:words:1:zh":"(topic)","grammar:1418:ex4:words:1:pos":"particle","grammar:1418:ex4:words:2:zh":"adult","grammar:1418:ex4:words:2:note":"おとな","grammar:1418:ex4:words:2:pos":"noun","grammar:1418:ex4:words:3:zh":"only","grammar:1418:ex4:words:3:pos":"particle","grammar:1418:ex4:words:4:zh":"'s","grammar:1418:ex4:words:4:pos":"particle","grammar:1418:ex4:words:5:zh":"gathering","grammar:1418:ex4:words:5:note":"あつまり","grammar:1418:ex4:words:5:pos":"noun","grammar:1418:ex4:words:6:zh":"(nominative)","grammar:1418:ex4:words:6:pos":"particle","grammar:1418:ex4:words:7:zh":"there is / are","grammar:1418:ex4:words:7:pos":"verb","grammar:1418:ex4:points:0":"❗〜だけの: for… only, … only; 集まり = gathering (the noun form of 集まる).","grammar:1418:ex4:points:1":"大人だけ: adults only.","grammar:1418:ex5:trans":"Adults must take responsibility.","grammar:1418:ex5:structure":"〜を持たなければなりません","grammar:1418:ex5:words:0:zh":"adult","grammar:1418:ex5:words:0:note":"おとな","grammar:1418:ex5:words:0:pos":"noun","grammar:1418:ex5:words:1:zh":"(topic)","grammar:1418:ex5:words:1:pos":"particle","grammar:1418:ex5:words:2:zh":"responsibility","grammar:1418:ex5:words:2:note":"せきにん","grammar:1418:ex5:words:2:pos":"noun","grammar:1418:ex5:words:3:zh":"(object marker)","grammar:1418:ex5:words:3:pos":"particle","grammar:1418:ex5:words:4:zh":"must take on","grammar:1418:ex5:words:4:note":"もたなければなりません","grammar:1418:ex5:words:4:pos":"verb","grammar:1418:ex5:points:0":"❗責任を持つ: to take responsibility (fixed expression); 〜なければなりません = must…","grammar:1418:ex5:points:1":"責任を持つ: to bear responsibility.","exam:1418:zh":"These clothes aren't for children; they're clothes for large adults to wear.","exam:1418:why":"「大人」 contrasts with the earlier 「子供」. 「男の子」 means boy, which is still a child."},"1419":{"example:1419:exzh":"Specific conditions are required.","example:1419:exzh2":"Let's talk about this particular project.","example:1419:exzh3":"I have a specific qualification.","example:1419:exzh4":"I'm working on a specific problem.","example:1419:exzh5":"There are specific rules."},"1420":{"example:1420:exzh":"He is a master of cooking.","example:1420:exzh2":"There's a lot to learn from a master.","example:1420:exzh3":"She is a master of languages.","example:1420:exzh4":"Skills as a master are required.","example:1420:exzh5":"I want to become a master of this game."},"1421":{"example:1421:exzh":"There are many booths at the event.","example:1421:exzh2":"I bought products at a booth.","example:1421:exzh3":"This booth is popular.","example:1421:exzh4":"The booth needs to be set up.","example:1421:exzh5":"We will introduce new products at the booth."},"1422":{"example:1422:exzh":"My cat is very cute.","example:1422:exzh2":"The cat is sleeping.","example:1422:exzh3":"Do you have a cat?","example:1422:exzh4":"I can hear a cat meowing.","example:1422:exzh5":"I like playing with cats.","grammar:1422:ex:trans":"My cat is very cute.","grammar:1422:ex:structure":"〜の猫は可愛いです","grammar:1422:ex:explain":"This combines a noun sentence with an i-adjective predicate. 「私の猫は」 uses 「の」 for possession (my cat) and 「は」 to mark the topic. 「可愛い」 is an i-adjective, here as the predicate, and 「です」 follows directly to make it polite: 「可愛いです」 = is cute. Note that an i-adjective keeps the same form before 「です」; no extra word is needed, unlike na-adjectives, which take 「な」. The whole sentence is an objective yet slightly subjective boast about how cute my cat is.","grammar:1422:ex:words:0:zh":"I","grammar:1422:ex:words:0:note":"わたし","grammar:1422:ex:words:0:pos":"pronoun","grammar:1422:ex:words:1:zh":"'s","grammar:1422:ex:words:1:pos":"particle","grammar:1422:ex:words:2:zh":"cat","grammar:1422:ex:words:2:note":"ねこ","grammar:1422:ex:words:2:pos":"noun","grammar:1422:ex:words:3:zh":"(topic)","grammar:1422:ex:words:3:pos":"particle","grammar:1422:ex:words:4:zh":"cute","grammar:1422:ex:words:4:note":"かわいい","grammar:1422:ex:words:4:pos":"adjective","grammar:1422:ex:words:5:zh":"(polite form)","grammar:1422:ex:words:5:pos":"copula","grammar:1422:ex:points:0":"❗猫（ねこ）: cat; 可愛い = cute.","grammar:1422:ex:points:1":"私の猫: my cat.","grammar:1422:ex2:trans":"The cat is sleeping.","grammar:1422:ex2:structure":"〜が寝ています","grammar:1422:ex2:words:0:zh":"cat","grammar:1422:ex2:words:0:note":"ねこ","grammar:1422:ex2:words:0:pos":"noun","grammar:1422:ex2:words:1:zh":"(nominative)","grammar:1422:ex2:words:1:pos":"particle","grammar:1422:ex2:words:2:zh":"asleep","grammar:1422:ex2:words:2:note":"ねています","grammar:1422:ex2:words:2:pos":"verb","grammar:1422:ex2:points:0":"❗寝る: to sleep (intransitive verb); 〜ている = is …ing.","grammar:1422:ex2:points:1":"猫が寝る: the cat sleeps.","grammar:1422:ex3:trans":"Do you have a cat?","grammar:1422:ex3:structure":"〜を飼っていますか","grammar:1422:ex3:words:0:zh":"cat","grammar:1422:ex3:words:0:note":"ねこ","grammar:1422:ex3:words:0:pos":"noun","grammar:1422:ex3:words:1:zh":"(object marker)","grammar:1422:ex3:words:1:pos":"particle","grammar:1422:ex3:words:2:zh":"keeping (a pet)","grammar:1422:ex3:words:2:note":"かっています","grammar:1422:ex3:words:2:pos":"verb","grammar:1422:ex3:words:3:zh":"(question)","grammar:1422:ex3:words:3:pos":"particle","grammar:1422:ex3:points:0":"❗猫を飼う: to keep a cat (飼う = to keep an animal).","grammar:1422:ex3:points:1":"飼う: to keep (an animal).","grammar:1422:ex4:trans":"You can hear a cat meowing.","grammar:1422:ex4:structure":"〜が聞こえる","grammar:1422:ex4:words:0:zh":"cat","grammar:1422:ex4:words:0:note":"ねこ","grammar:1422:ex4:words:0:pos":"noun","grammar:1422:ex4:words:1:zh":"'s","grammar:1422:ex4:words:1:pos":"particle","grammar:1422:ex4:words:2:zh":"cries","grammar:1422:ex4:words:2:note":"なきごえ","grammar:1422:ex4:words:2:pos":"noun","grammar:1422:ex4:words:3:zh":"(nominative)","grammar:1422:ex4:words:3:pos":"particle","grammar:1422:ex4:words:4:zh":"can hear","grammar:1422:ex4:words:4:note":"きこえる","grammar:1422:ex4:words:4:pos":"verb","grammar:1422:ex4:points:0":"❗鳴き声: (animal) call, cry; 聞こえる = to be able to hear.","grammar:1422:ex4:points:1":"猫の鳴き声: a cat's meow.","grammar:1422:ex5:trans":"I like playing with cats.","grammar:1422:ex5:structure":"〜のが好きです","grammar:1422:ex5:words:0:zh":"cat","grammar:1422:ex5:words:0:note":"ねこ","grammar:1422:ex5:words:0:pos":"noun","grammar:1422:ex5:words:1:zh":"with","grammar:1422:ex5:words:1:pos":"particle","grammar:1422:ex5:words:2:zh":"hang out","grammar:1422:ex5:words:2:note":"あそぶ","grammar:1422:ex5:words:2:pos":"verb","grammar:1422:ex5:words:3:zh":"(nominalizer)","grammar:1422:ex5:words:3:pos":"particle","grammar:1422:ex5:words:4:zh":"(object)","grammar:1422:ex5:words:4:pos":"particle","grammar:1422:ex5:words:5:zh":"to like","grammar:1422:ex5:words:5:note":"すき","grammar:1422:ex5:words:5:pos":"na-adjective","grammar:1422:ex5:words:6:zh":"(polite form)","grammar:1422:ex5:words:6:pos":"copula","grammar:1422:ex5:points:0":"❗猫と遊ぶ: to play with a cat; 〜のが好き = to like doing…","grammar:1422:ex5:points:1":"遊ぶ: to play.","exam:1422:zh":"My cat meows when it gets hungry.","exam:1422:why":"「ニャー」 is the cry of a 「猫」. A dog's bark is usually written 「ワンワン」."},"1423":{"example:1423:exzh":"She is pregnant.","example:1423:exzh2":"The early stage of pregnancy is important.","example:1423:exzh3":"I took a pregnancy test.","example:1423:exzh4":"Managing your health during pregnancy is important.","example:1423:exzh5":"You need knowledge about pregnancy."},"1424":{"example:1424:exzh":"He swore revenge.","example:1424:exzh2":"Revenge isn't desirable.","example:1424:exzh3":"You shouldn't harbor a desire for revenge.","example:1424:exzh4":"The movie is a story about revenge.","example:1424:exzh5":"Revenge brings no peace."},"1425":{"example:1425:exzh":"It's about time to go.","example:1425:exzh2":"I think he'll be here soon.","example:1425:exzh3":"It's about time to start homework.","example:1425:exzh4":"It's about time for a break.","example:1425:exzh5":"Winter is almost here.","grammar:1425:ex:trans":"It's about time to leave.","grammar:1425:ex:structure":"そろそろ〜時間です","grammar:1425:ex:explain":"The key word here is the adverb 「そろそろ」, which means the moment is almost here—it's about time to do something. It often comes at the start of a sentence and hints that the time for something is approaching, with a slight tone of reminding or urging. 「行く時間」 means the time to leave, so 「そろそろ〜時間です」 means it's about time to…. The sentence ends with 「です」, which states a judgment, and the whole thing is a very everyday expression, often used when getting ready to leave or set off.","grammar:1425:ex:words:0:zh":"about time","grammar:1425:ex:words:0:pos":"adverb","grammar:1425:ex:words:1:zh":"go","grammar:1425:ex:words:1:note":"いく","grammar:1425:ex:words:1:pos":"verb","grammar:1425:ex:words:2:zh":"time","grammar:1425:ex:words:2:note":"じかん","grammar:1425:ex:words:2:pos":"noun","grammar:1425:ex:words:3:zh":"is","grammar:1425:ex:words:3:pos":"copula","grammar:1425:ex:points:0":"❗そろそろ: almost, about time (marks that the moment is approaching).","grammar:1425:ex:points:1":"そろそろ〜時間: it's about time to…","grammar:1425:ex2:trans":"I think he'll be here soon.","grammar:1425:ex2:structure":"そろそろ〜と思います","grammar:1425:ex2:words:0:zh":"soon","grammar:1425:ex2:words:0:pos":"adverb","grammar:1425:ex2:words:1:zh":"he","grammar:1425:ex2:words:1:note":"かれ","grammar:1425:ex2:words:1:pos":"pronoun","grammar:1425:ex2:words:2:zh":"(nominative)","grammar:1425:ex2:words:2:pos":"particle","grammar:1425:ex2:words:3:zh":"come","grammar:1425:ex2:words:3:note":"くる","grammar:1425:ex2:words:3:pos":"verb","grammar:1425:ex2:words:4:zh":"(quotation)","grammar:1425:ex2:words:4:pos":"particle","grammar:1425:ex2:words:5:zh":"think","grammar:1425:ex2:words:5:note":"おもいます","grammar:1425:ex2:words:5:pos":"verb","grammar:1425:ex2:points:0":"❗そろそろ〜と思う: to feel that something is about to happen.","grammar:1425:ex2:points:1":"来る: to come.","grammar:1425:ex3:trans":"It's about time to start my homework.","grammar:1425:ex3:structure":"そろそろ〜なければなりません","grammar:1425:ex3:words:0:zh":"about time","grammar:1425:ex3:words:0:pos":"adverb","grammar:1425:ex3:words:1:zh":"homework","grammar:1425:ex3:words:1:note":"しゅくだい","grammar:1425:ex3:words:1:pos":"noun","grammar:1425:ex3:words:2:zh":"(object marker)","grammar:1425:ex3:words:2:pos":"particle","grammar:1425:ex3:words:3:zh":"have to start","grammar:1425:ex3:words:3:note":"はじめなければなりません","grammar:1425:ex3:words:3:pos":"verb","grammar:1425:ex3:points:0":"❗〜なければなりません: must…; そろそろ = it's about time.","grammar:1425:ex3:points:1":"始める: to begin.","grammar:1425:ex4:trans":"It's about time we took a break.","grammar:1425:ex4:structure":"そろそろ〜が必要です","grammar:1425:ex4:words:0:zh":"about time","grammar:1425:ex4:words:0:pos":"adverb","grammar:1425:ex4:words:1:zh":"rest","grammar:1425:ex4:words:1:note":"きゅうけい","grammar:1425:ex4:words:1:pos":"noun","grammar:1425:ex4:words:2:zh":"(nominative)","grammar:1425:ex4:words:2:pos":"particle","grammar:1425:ex4:words:3:zh":"necessary","grammar:1425:ex4:words:3:note":"ひつよう","grammar:1425:ex4:words:3:pos":"na-adjective","grammar:1425:ex4:words:4:zh":"(polite form)","grammar:1425:ex4:words:4:pos":"copula","grammar:1425:ex4:points:0":"❗休憩: a break; そろそろ必要 = needed about now.","grammar:1425:ex4:points:1":"休憩: a break.","grammar:1425:ex5:trans":"Winter is almost here.","grammar:1425:ex5:structure":"そろそろ〜がやってきます","grammar:1425:ex5:words:0:zh":"soon","grammar:1425:ex5:words:0:pos":"adverb","grammar:1425:ex5:words:1:zh":"winter","grammar:1425:ex5:words:1:note":"ふゆ","grammar:1425:ex5:words:1:pos":"noun","grammar:1425:ex5:words:2:zh":"(nominative)","grammar:1425:ex5:words:2:pos":"particle","grammar:1425:ex5:words:3:zh":"approach","grammar:1425:ex5:words:3:pos":"verb","grammar:1425:ex5:points:0":"❗やってくる: to come, to arrive; そろそろ = soon.","grammar:1425:ex5:points:1":"冬がやってくる: winter is coming."},"1426":{"example:1426:exzh":"I clean every Saturday.","example:1426:exzh2":"Cleaning the house is fun.","example:1426:exzh3":"After cleaning, the room becomes tidy.","example:1426:exzh4":"He is good at cleaning.","example:1426:exzh5":"Thanks for helping me clean.","grammar:1426:ex:trans":"I clean every Saturday.","grammar:1426:ex:structure":"〜に掃除をします","grammar:1426:ex:explain":"This sentence demonstrates the pattern noun + 「を」 + する. 「掃除」 is a noun on its own, but adding 「を」 and then 「します」 turns it into the action of cleaning, so 「掃除をします」 means to do the cleaning. You can also simply say 「掃除します」 with the same meaning. The 「に」 in 「毎週土曜日に」 marks a fixed point in time, showing that this is done every Saturday. The sentence describes a regular habit in a polite, objective tone.","grammar:1426:ex:words:0:zh":"every week","grammar:1426:ex:words:0:note":"まいしゅう","grammar:1426:ex:words:0:pos":"adverb","grammar:1426:ex:words:1:zh":"Saturday","grammar:1426:ex:words:1:note":"どようび","grammar:1426:ex:words:1:pos":"noun","grammar:1426:ex:words:2:zh":"(point in time)","grammar:1426:ex:words:2:pos":"particle","grammar:1426:ex:words:3:zh":"cleaning","grammar:1426:ex:words:3:note":"そうじ","grammar:1426:ex:words:3:pos":"noun","grammar:1426:ex:words:4:zh":"(object marker)","grammar:1426:ex:words:4:pos":"particle","grammar:1426:ex:words:5:zh":"do","grammar:1426:ex:words:5:pos":"verb","grammar:1426:ex:points:0":"❗掃除（そうじ）: cleaning; 掃除をする = to clean; 〜曜日に = on… (day of the week).","grammar:1426:ex:points:1":"掃除をする: to clean.","grammar:1426:ex2:trans":"Cleaning the house is fun.","grammar:1426:ex2:structure":"〜の掃除は楽しいです","grammar:1426:ex2:words:0:zh":"house","grammar:1426:ex2:words:0:note":"いえ","grammar:1426:ex2:words:0:pos":"noun","grammar:1426:ex2:words:1:zh":"'s","grammar:1426:ex2:words:1:pos":"particle","grammar:1426:ex2:words:2:zh":"cleaning","grammar:1426:ex2:words:2:note":"そうじ","grammar:1426:ex2:words:2:pos":"noun","grammar:1426:ex2:words:3:zh":"(topic)","grammar:1426:ex2:words:3:pos":"particle","grammar:1426:ex2:words:4:zh":"interesting","grammar:1426:ex2:words:4:note":"たのしい","grammar:1426:ex2:words:4:pos":"adjective","grammar:1426:ex2:words:5:zh":"(polite form)","grammar:1426:ex2:words:5:pos":"copula","grammar:1426:ex2:points:0":"家の掃除: cleaning the house.","grammar:1426:ex2:points:1":"楽しい: fun.","grammar:1426:ex3:trans":"After cleaning, the room becomes nice and tidy.","grammar:1426:ex3:structure":"〜の後は〜になります","grammar:1426:ex3:words:0:zh":"cleaning","grammar:1426:ex3:words:0:note":"そうじ","grammar:1426:ex3:words:0:pos":"noun","grammar:1426:ex3:words:1:zh":"'s","grammar:1426:ex3:words:1:pos":"particle","grammar:1426:ex3:words:2:zh":"later, afterwards","grammar:1426:ex3:words:2:note":"あと","grammar:1426:ex3:words:2:pos":"noun","grammar:1426:ex3:words:3:zh":"(topic)","grammar:1426:ex3:words:3:pos":"particle","grammar:1426:ex3:words:4:zh":"room","grammar:1426:ex3:words:4:note":"へや","grammar:1426:ex3:words:4:pos":"noun","grammar:1426:ex3:words:5:zh":"(nominative)","grammar:1426:ex3:words:5:pos":"particle","grammar:1426:ex3:words:6:zh":"clean","grammar:1426:ex3:words:6:note":"きれい","grammar:1426:ex3:words:6:pos":"na-adjective","grammar:1426:ex3:words:7:zh":"(result)","grammar:1426:ex3:words:7:pos":"particle","grammar:1426:ex3:words:8:zh":"become","grammar:1426:ex3:words:8:pos":"verb","grammar:1426:ex3:points:0":"❗〜の後: after…; 綺麗になる = to become clean.","grammar:1426:ex3:points:1":"掃除の後: after cleaning.","grammar:1426:ex4:trans":"He's good at cleaning.","grammar:1426:ex4:structure":"〜が得意です","grammar:1426:ex4:words:0:zh":"he","grammar:1426:ex4:words:0:note":"かれ","grammar:1426:ex4:words:0:pos":"pronoun","grammar:1426:ex4:words:1:zh":"(topic)","grammar:1426:ex4:words:1:pos":"particle","grammar:1426:ex4:words:2:zh":"cleaning","grammar:1426:ex4:words:2:note":"そうじ","grammar:1426:ex4:words:2:pos":"noun","grammar:1426:ex4:words:3:zh":"(object)","grammar:1426:ex4:words:3:pos":"particle","grammar:1426:ex4:words:4:zh":"good at","grammar:1426:ex4:words:4:note":"とくい","grammar:1426:ex4:words:4:pos":"na-adjective","grammar:1426:ex4:words:5:zh":"(polite form)","grammar:1426:ex4:words:5:pos":"copula","grammar:1426:ex4:points:0":"掃除が得意: good at cleaning.","grammar:1426:ex4:points:1":"得意: good at.","grammar:1426:ex5:trans":"Thanks for helping with the cleaning.","grammar:1426:ex5:structure":"〜を手伝ってくれてありがとう","grammar:1426:ex5:words:0:zh":"cleaning","grammar:1426:ex5:words:0:note":"そうじ","grammar:1426:ex5:words:0:pos":"noun","grammar:1426:ex5:words:1:zh":"(object marker)","grammar:1426:ex5:words:1:pos":"particle","grammar:1426:ex5:words:2:zh":"help","grammar:1426:ex5:words:2:note":"てつだって","grammar:1426:ex5:words:2:pos":"verb","grammar:1426:ex5:words:3:zh":"makes (for me)","grammar:1426:ex5:words:3:pos":"auxiliary verb","grammar:1426:ex5:words:4:zh":"thank you","grammar:1426:ex5:words:4:pos":"set phrase","grammar:1426:ex5:points:0":"❗〜てくれてありがとう: thank you for doing… for me; 掃除を手伝う = to help with the cleaning.","grammar:1426:ex5:points:1":"手伝う: to help."},"1427":{"example:1427:exzh":"This problem is complicated.","example:1427:exzh2":"I think his feelings are complicated.","example:1427:exzh3":"Her family relationships are complicated.","example:1427:exzh4":"This machine is complicated to use.","example:1427:exzh5":"This city has a lot of complicated roads.","grammar:1427:ex:trans":"This problem is complicated.","grammar:1427:ex:structure":"〜は複雑です","grammar:1427:ex:explain":"This is a sentence with a na-adjective as the predicate: 「〜は複雑です」. 「複雑」 (complicated) is a na-adjective; as a predicate it takes 「です」 directly to become polite, so 「複雑です」 means it's complicated—no 「な」 is needed here. The 「な」 only appears when the adjective modifies a noun (複雑な問題). The preceding 「この問題は」 uses 「は」 to mark the topic. The sentence objectively comments that the problem isn't simple, in a polite tone.","grammar:1427:ex:words:0:zh":"this","grammar:1427:ex:words:0:pos":"pre-noun adjectival","grammar:1427:ex:words:1:zh":"problem","grammar:1427:ex:words:1:note":"もんだい","grammar:1427:ex:words:1:pos":"noun","grammar:1427:ex:words:2:zh":"(topic)","grammar:1427:ex:words:2:pos":"particle","grammar:1427:ex:words:3:zh":"complicated","grammar:1427:ex:words:3:note":"ふくざつ","grammar:1427:ex:words:3:pos":"na-adjective","grammar:1427:ex:words:4:zh":"(polite form)","grammar:1427:ex:words:4:pos":"copula","grammar:1427:ex:points:0":"❗複雑（ふくざつ）: complicated (na-adjective).","grammar:1427:ex:points:1":"複雑な問題: a complicated problem.","grammar:1427:ex2:trans":"I think his feelings are complicated.","grammar:1427:ex2:structure":"〜は複雑だと思います","grammar:1427:ex2:words:0:zh":"he","grammar:1427:ex2:words:0:note":"かれ","grammar:1427:ex2:words:0:pos":"pronoun","grammar:1427:ex2:words:1:zh":"'s","grammar:1427:ex2:words:1:pos":"particle","grammar:1427:ex2:words:2:zh":"feeling","grammar:1427:ex2:words:2:note":"きもち","grammar:1427:ex2:words:2:pos":"noun","grammar:1427:ex2:words:3:zh":"(topic)","grammar:1427:ex2:words:3:pos":"particle","grammar:1427:ex2:words:4:zh":"complicated","grammar:1427:ex2:words:4:note":"ふくざつ","grammar:1427:ex2:words:4:pos":"na-adjective","grammar:1427:ex2:words:5:zh":"is","grammar:1427:ex2:words:5:pos":"copula","grammar:1427:ex2:words:6:zh":"(quotation)","grammar:1427:ex2:words:6:pos":"particle","grammar:1427:ex2:words:7:zh":"think","grammar:1427:ex2:words:7:note":"おもいます","grammar:1427:ex2:words:7:pos":"verb","grammar:1427:ex2:points:0":"❗〜だと思います: I think…; 複雑な気持ち = complicated feelings.","grammar:1427:ex2:points:1":"気持ち: feelings.","grammar:1427:ex3:trans":"Her family relationships are complicated.","grammar:1427:ex3:structure":"〜の家族の関係は複雑です","grammar:1427:ex3:explain":"The first 「の」 links 「彼女」 to 「家族」, forming her family; the second 「の」 then links that phrase to 「関係」, showing that the topic is the relationships within her family. 「は」 makes the whole noun phrase the topic. 「複雑です」 describes those relationships as complicated, and as a sentence-final predicate it takes no 「な」.","grammar:1427:ex3:words:0:zh":"she","grammar:1427:ex3:words:0:note":"かのじょ","grammar:1427:ex3:words:0:pos":"pronoun","grammar:1427:ex3:words:1:zh":"(possession)","grammar:1427:ex3:words:1:pos":"particle","grammar:1427:ex3:words:2:zh":"family, household","grammar:1427:ex3:words:2:note":"かぞく","grammar:1427:ex3:words:2:pos":"noun","grammar:1427:ex3:words:3:zh":"(modifies the scope of the relationship)","grammar:1427:ex3:words:3:pos":"particle","grammar:1427:ex3:words:4:zh":"relationship","grammar:1427:ex3:words:4:note":"かんけい","grammar:1427:ex3:words:4:pos":"noun","grammar:1427:ex3:words:5:zh":"(topic)","grammar:1427:ex3:words:5:pos":"particle","grammar:1427:ex3:words:6:zh":"complicated","grammar:1427:ex3:words:6:note":"ふくざつ","grammar:1427:ex3:words:6:pos":"na-adjective","grammar:1427:ex3:words:7:zh":"(polite tone)","grammar:1427:ex3:words:7:pos":"auxiliary verb","grammar:1427:ex3:points:0":"Chained 「の」 can link nouns layer by layer, so 「彼女の家族の関係」 means the relationships of her family.","grammar:1427:ex3:points:1":"「複雑」 is a na-adjective: at the end of a sentence you say 「複雑です」, and when modifying a noun you say 「複雑な関係」.","grammar:1427:ex4:trans":"This machine is complicated to use.","grammar:1427:ex4:structure":"〜は使い方が複雑です","grammar:1427:ex4:words:0:zh":"this","grammar:1427:ex4:words:0:pos":"pre-noun adjectival","grammar:1427:ex4:words:1:zh":"machine","grammar:1427:ex4:words:1:note":"きかい","grammar:1427:ex4:words:1:pos":"noun","grammar:1427:ex4:words:2:zh":"(topic)","grammar:1427:ex4:words:2:pos":"particle","grammar:1427:ex4:words:3:zh":"usage","grammar:1427:ex4:words:3:note":"つかいかた","grammar:1427:ex4:words:3:pos":"noun","grammar:1427:ex4:words:4:zh":"(nominative)","grammar:1427:ex4:words:4:pos":"particle","grammar:1427:ex4:words:5:zh":"complicated","grammar:1427:ex4:words:5:note":"ふくざつ","grammar:1427:ex4:words:5:pos":"na-adjective","grammar:1427:ex4:words:6:zh":"(polite form)","grammar:1427:ex4:words:6:pos":"copula","grammar:1427:ex4:points:0":"❗使い方: how to use something (使う + 方); 使い方が複雑 = complicated to operate.","grammar:1427:ex4:points:1":"使い方: how to use.","grammar:1427:ex5:trans":"This city has many complicated streets.","grammar:1427:ex5:structure":"〜は複雑な〜が多いです","grammar:1427:ex5:words:0:zh":"this","grammar:1427:ex5:words:0:pos":"pre-noun adjectival","grammar:1427:ex5:words:1:zh":"city","grammar:1427:ex5:words:1:note":"まち","grammar:1427:ex5:words:1:pos":"noun","grammar:1427:ex5:words:2:zh":"(topic)","grammar:1427:ex5:words:2:pos":"particle","grammar:1427:ex5:words:3:zh":"complicated","grammar:1427:ex5:words:3:note":"ふくざつ","grammar:1427:ex5:words:3:pos":"na-adjective","grammar:1427:ex5:words:4:zh":"(attributive form)","grammar:1427:ex5:words:4:pos":"auxiliary verb","grammar:1427:ex5:words:5:zh":"road","grammar:1427:ex5:words:5:note":"みち","grammar:1427:ex5:words:5:pos":"noun","grammar:1427:ex5:words:6:zh":"(nominative)","grammar:1427:ex5:words:6:pos":"particle","grammar:1427:ex5:words:7:zh":"many","grammar:1427:ex5:words:7:note":"おおい","grammar:1427:ex5:words:7:pos":"adjective","grammar:1427:ex5:words:8:zh":"(polite form)","grammar:1427:ex5:words:8:pos":"copula","grammar:1427:ex5:points:0":"複雑な道: tangled streets.","grammar:1427:ex5:points:1":"道が多い: there are many streets."},"1428":{"example:1428:exzh":"A lot of time has passed.","example:1428:exzh2":"I look back on the days that have passed.","example:1428:exzh3":"Her growth has been an amazing process.","example:1428:exzh4":"I don't remember how many years have passed.","example:1428:exzh5":"Please don't forget the events that have passed."},"1429":{"example:1429:exzh":"I made travel arrangements.","example:1429:exzh2":"The arrangements are set, so we're leaving.","example:1429:exzh3":"Please let me know if arrangements are needed.","example:1429:exzh4":"He's good at making arrangements.","example:1429:exzh5":"All the arrangements are going smoothly."},"1430":{"example:1430:exzh":"The sky is blue.","example:1430:exzh2":"The blue ocean spreads out before us.","example:1430:exzh3":"I like blue flowers.","example:1430:exzh4":"He is wearing blue clothes.","example:1430:exzh5":"White clouds are floating in the blue sky.","grammar:1430:ex:trans":"The sky is blue.","grammar:1430:ex:structure":"〜は青いです","grammar:1430:ex:explain":"This is a sentence with an i-adjective as the predicate: 「〜は青いです」. 「青い」 is an i-adjective and can stand as the predicate on its own; adding 「です」 makes it polite, so 「青いです」 means it's blue. Note that the i-adjective already carries the meaning of is, and 「です」 only adds politeness—you can't make it 「青いだ」. The preceding 「空は」 uses 「は」 to mark the topic. The sentence is a very basic color description: the sky is blue.","grammar:1430:ex:words:0:zh":"sky","grammar:1430:ex:words:0:note":"そら","grammar:1430:ex:words:0:pos":"noun","grammar:1430:ex:words:1:zh":"(topic)","grammar:1430:ex:words:1:pos":"particle","grammar:1430:ex:words:2:zh":"blue","grammar:1430:ex:words:2:note":"あおい","grammar:1430:ex:words:2:pos":"adjective","grammar:1430:ex:words:3:zh":"(polite form)","grammar:1430:ex:words:3:pos":"copula","grammar:1430:ex:points:0":"❗青（あお）: blue; 青い = blue (i-adjective).","grammar:1430:ex:points:1":"空が青い: the sky is blue.","grammar:1430:ex2:trans":"The blue sea stretches out.","grammar:1430:ex2:structure":"青い〜が広がっている","grammar:1430:ex2:words:0:zh":"blue","grammar:1430:ex2:words:0:note":"あおい","grammar:1430:ex2:words:0:pos":"adjective","grammar:1430:ex2:words:1:zh":"sea","grammar:1430:ex2:words:1:note":"うみ","grammar:1430:ex2:words:1:pos":"noun","grammar:1430:ex2:words:2:zh":"(nominative)","grammar:1430:ex2:words:2:pos":"particle","grammar:1430:ex2:words:3:zh":"stretching out","grammar:1430:ex2:words:3:note":"ひろがっている","grammar:1430:ex2:words:3:pos":"verb","grammar:1430:ex2:points:0":"❗広がる: to spread, to extend (intransitive verb); 青い海 = the blue sea.","grammar:1430:ex2:points:1":"海が広がる: the sea spreads out wide.","grammar:1430:ex3:trans":"I like blue flowers.","grammar:1430:ex3:structure":"青い〜が好きです","grammar:1430:ex3:words:0:zh":"blue","grammar:1430:ex3:words:0:note":"あおい","grammar:1430:ex3:words:0:pos":"adjective","grammar:1430:ex3:words:1:zh":"flowers","grammar:1430:ex3:words:1:note":"はな","grammar:1430:ex3:words:1:pos":"noun","grammar:1430:ex3:words:2:zh":"(object)","grammar:1430:ex3:words:2:pos":"particle","grammar:1430:ex3:words:3:zh":"to like","grammar:1430:ex3:words:3:note":"すき","grammar:1430:ex3:words:3:pos":"na-adjective","grammar:1430:ex3:words:4:zh":"(polite form)","grammar:1430:ex3:words:4:pos":"copula","grammar:1430:ex3:points:0":"青い花: blue flowers.","grammar:1430:ex3:points:1":"〜が好き: to like …","grammar:1430:ex4:trans":"He's wearing blue clothes.","grammar:1430:ex4:structure":"青い〜を着ています","grammar:1430:ex4:words:0:zh":"he","grammar:1430:ex4:words:0:note":"かれ","grammar:1430:ex4:words:0:pos":"pronoun","grammar:1430:ex4:words:1:zh":"(topic)","grammar:1430:ex4:words:1:pos":"particle","grammar:1430:ex4:words:2:zh":"blue","grammar:1430:ex4:words:2:note":"あおい","grammar:1430:ex4:words:2:pos":"adjective","grammar:1430:ex4:words:3:zh":"clothes","grammar:1430:ex4:words:3:note":"ふく","grammar:1430:ex4:words:3:pos":"noun","grammar:1430:ex4:words:4:zh":"(object marker)","grammar:1430:ex4:words:4:pos":"particle","grammar:1430:ex4:words:5:zh":"Wearing","grammar:1430:ex4:words:5:note":"きています","grammar:1430:ex4:words:5:pos":"verb","grammar:1430:ex4:points:0":"青い服: blue clothes.","grammar:1430:ex4:points:1":"〜を着ている: to be wearing …","grammar:1430:ex5:trans":"White clouds float in the blue sky.","grammar:1430:ex5:structure":"〜に〜が浮かんでいる","grammar:1430:ex5:words:0:zh":"blue","grammar:1430:ex5:words:0:note":"あおい","grammar:1430:ex5:words:0:pos":"adjective","grammar:1430:ex5:words:1:zh":"sky","grammar:1430:ex5:words:1:note":"そら","grammar:1430:ex5:words:1:pos":"noun","grammar:1430:ex5:words:2:zh":"(location of existence)","grammar:1430:ex5:words:2:pos":"particle","grammar:1430:ex5:words:3:zh":"white","grammar:1430:ex5:words:3:note":"しろい","grammar:1430:ex5:words:3:pos":"adjective","grammar:1430:ex5:words:4:zh":"clouds","grammar:1430:ex5:words:4:note":"くも","grammar:1430:ex5:words:4:pos":"noun","grammar:1430:ex5:words:5:zh":"(nominative)","grammar:1430:ex5:words:5:pos":"particle","grammar:1430:ex5:words:6:zh":"is floating","grammar:1430:ex5:words:6:note":"うかんでいる","grammar:1430:ex5:words:6:pos":"verb","grammar:1430:ex5:points:0":"❗浮かぶ: to float, to come to the surface (intransitive verb); 青い空／白い雲 = blue sky and white clouds.","grammar:1430:ex5:points:1":"雲が浮かぶ: clouds float.","exam:1430:zh":"This pencil is neither yellow nor red, but blue like a clear sky.","exam:1430:why":"The typical color of a clear sky is 「青い」. 「白い」 can describe clouds, but here the comparison is the color of the sky.","exam_official:1430:zh":"That blue car is my teacher's.","exam_official:1430:why":"「あおい」, meaning blue, is written 「青い」. 「清」 does contain 「青」, but it isn't the spelling of this color word."},"1431":{"example:1431:exzh":"I repaired the bicycle.","example:1431:exzh2":"Can you fix this broken watch?","example:1431:exzh3":"It's best to have a professional do the repairs.","example:1431:exzh4":"He's good at fixing houses.","example:1431:exzh5":"The repair costs are so high that I'm in a bind.","grammar:1431:ex:trans":"I repaired a bicycle.","grammar:1431:ex:structure":"〜を修理しました","grammar:1431:ex:explain":"This sentence uses the compound form noun + する. 「修理する」 is a suru-verb made from the noun 「修理」 plus 「する」, and 「を」 marks the object of the repair, 「自転車」, so 「自転車を修理する」 means to repair a bicycle. 「修理しました」 is the polite past form, showing it's been fixed and the job is done. The sentence states an action by 「私は」 (omitted here) in a polite tone. Japanese has a great many verbs of this noun + する type.","grammar:1431:ex:words:0:zh":"bicycle","grammar:1431:ex:words:0:note":"じてんしゃ","grammar:1431:ex:words:0:pos":"noun","grammar:1431:ex:words:1:zh":"(object marker)","grammar:1431:ex:words:1:pos":"particle","grammar:1431:ex:words:2:zh":"repaired","grammar:1431:ex:words:2:note":"しゅうりしました","grammar:1431:ex:words:2:pos":"verb","grammar:1431:ex:points:0":"❗修理する: to repair; 自転車 = bicycle.","grammar:1431:ex:points:1":"自転車を修理: to repair a bicycle.","grammar:1431:ex2:trans":"Can you fix this broken watch?","grammar:1431:ex2:structure":"壊れた〜を修理できる","grammar:1431:ex2:words:0:zh":"this","grammar:1431:ex2:words:0:pos":"pre-noun adjectival","grammar:1431:ex2:words:1:zh":"broken","grammar:1431:ex2:words:1:note":"こわれた","grammar:1431:ex2:words:1:pos":"verb","grammar:1431:ex2:words:2:zh":"watch","grammar:1431:ex2:words:2:note":"とけい","grammar:1431:ex2:words:2:pos":"noun","grammar:1431:ex2:words:3:zh":"(object marker)","grammar:1431:ex2:words:3:pos":"particle","grammar:1431:ex2:words:4:zh":"can fix","grammar:1431:ex2:words:4:note":"しゅうりできる","grammar:1431:ex2:words:4:pos":"verb","grammar:1431:ex2:points:0":"❗壊れた時計: a broken watch (pre-noun adjectival); 修理できる = can fix (potential form).","grammar:1431:ex2:points:1":"修理できる: to be able to fix.","grammar:1431:ex3:trans":"It's best to have a professional handle the repairs.","grammar:1431:ex3:structure":"〜に頼んだ方がいい","grammar:1431:ex3:words:0:zh":"repair","grammar:1431:ex3:words:0:note":"しゅうり","grammar:1431:ex3:words:0:pos":"noun","grammar:1431:ex3:words:1:zh":"(topic)","grammar:1431:ex3:words:1:pos":"particle","grammar:1431:ex3:words:2:zh":"specialty","grammar:1431:ex3:words:2:note":"せんもん","grammar:1431:ex3:words:2:pos":"noun","grammar:1431:ex3:words:3:zh":"'s","grammar:1431:ex3:words:3:pos":"particle","grammar:1431:ex3:words:4:zh":"person","grammar:1431:ex3:words:4:note":"ひと","grammar:1431:ex3:words:4:pos":"noun","grammar:1431:ex3:words:5:zh":"(object)","grammar:1431:ex3:words:5:pos":"particle","grammar:1431:ex3:words:6:zh":"request, commission","grammar:1431:ex3:words:6:note":"たのんだ","grammar:1431:ex3:words:6:pos":"verb","grammar:1431:ex3:words:7:zh":"it's better to","grammar:1431:ex3:words:7:note":"ほうがいい","grammar:1431:ex3:words:7:pos":"set phrase","grammar:1431:ex3:points:0":"❗〜た方がいい: it's better to… (advice); 〜に頼む = to ask someone to do…","grammar:1431:ex3:points:1":"頼んだ方がいい: it's better to ask someone to do it.","grammar:1431:ex4:trans":"He's good at fixing up houses.","grammar:1431:ex4:structure":"〜のが得意です","grammar:1431:ex4:words:0:zh":"he","grammar:1431:ex4:words:0:note":"かれ","grammar:1431:ex4:words:0:pos":"pronoun","grammar:1431:ex4:words:1:zh":"(topic)","grammar:1431:ex4:words:1:pos":"particle","grammar:1431:ex4:words:2:zh":"house","grammar:1431:ex4:words:2:note":"いえ","grammar:1431:ex4:words:2:pos":"noun","grammar:1431:ex4:words:3:zh":"(object marker)","grammar:1431:ex4:words:3:pos":"particle","grammar:1431:ex4:words:4:zh":"repair","grammar:1431:ex4:words:4:note":"しゅうりする","grammar:1431:ex4:words:4:pos":"verb","grammar:1431:ex4:words:5:zh":"(nominalizer)","grammar:1431:ex4:words:5:pos":"particle","grammar:1431:ex4:words:6:zh":"(object)","grammar:1431:ex4:words:6:pos":"particle","grammar:1431:ex4:words:7:zh":"good at","grammar:1431:ex4:words:7:note":"とくい","grammar:1431:ex4:words:7:pos":"na-adjective","grammar:1431:ex4:words:8:zh":"(polite form)","grammar:1431:ex4:words:8:pos":"copula","grammar:1431:ex4:points:0":"❗〜のが得意: to be good at doing…; 家を修理 = to repair a house.","grammar:1431:ex4:points:1":"得意: good at.","grammar:1431:ex5:trans":"The repair costs are so high that I'm in a bind.","grammar:1431:ex5:structure":"〜が高くて困っています","grammar:1431:ex5:words:0:zh":"repair costs","grammar:1431:ex5:words:0:note":"しゅうりだい","grammar:1431:ex5:words:0:pos":"noun","grammar:1431:ex5:words:1:zh":"(nominative)","grammar:1431:ex5:words:1:pos":"particle","grammar:1431:ex5:words:2:zh":"expensive, and","grammar:1431:ex5:words:2:note":"たかくて","grammar:1431:ex5:words:2:pos":"adjective","grammar:1431:ex5:words:3:zh":"to be troubled","grammar:1431:ex5:words:3:note":"こまっています","grammar:1431:ex5:words:3:pos":"verb","grammar:1431:ex5:points:0":"❗修理代: repair costs (修理 + 代); 〜くて = because… (i-adjective in its continuative form).","grammar:1431:ex5:points:1":"修理代が高い: the repair costs are high."},"1432":{"example:1432:exzh":"I can see the sun rising.","example:1432:exzh2":"The sun is blindingly bright today.","example:1432:exzh3":"The sunlight warms you up.","example:1432:exzh4":"The sun revolves around the earth.","example:1432:exzh5":"I like watching the sun at the seaside.","grammar:1432:ex:trans":"You can see the sun rise.","grammar:1432:ex:structure":"〜が昇るのが見えます","grammar:1432:ex:explain":"This sentence shows how 「の」 turns an action into a noun so it can be the object of perception. 「太陽が昇る」 is a sentence on its own (the sun rises, with the intransitive verb taking 「が」); adding 「の」 makes it the noun phrase the sun's rising (this event), and 「が」 then connects it to 「見えます」. 「見える」 means to be visible, to come into view—it stresses seeing something naturally rather than looking on purpose (that's 「見る」). The whole sentence means you can see the sun rise.","grammar:1432:ex:words:0:zh":"sun","grammar:1432:ex:words:0:note":"たいよう","grammar:1432:ex:words:0:pos":"noun","grammar:1432:ex:words:1:zh":"(nominative)","grammar:1432:ex:words:1:pos":"particle","grammar:1432:ex:words:2:zh":"rise","grammar:1432:ex:words:2:note":"のぼる","grammar:1432:ex:words:2:pos":"verb","grammar:1432:ex:words:3:zh":"(nominalizer)","grammar:1432:ex:words:3:pos":"particle","grammar:1432:ex:words:4:zh":"(nominative)","grammar:1432:ex:words:4:pos":"particle","grammar:1432:ex:words:5:zh":"can see (is visible)","grammar:1432:ex:words:5:note":"みえます","grammar:1432:ex:words:5:pos":"verb","grammar:1432:ex:points:0":"❗太陽（たいよう）: the sun; 昇る = to rise (intransitive verb); 〜のが見える = to be able to see…","grammar:1432:ex:points:1":"太陽が昇る: the sun rises.","grammar:1432:ex2:trans":"The sun is really dazzling today.","grammar:1432:ex2:structure":"〜が眩しいです","grammar:1432:ex2:words:0:zh":"today","grammar:1432:ex2:words:0:note":"きょう","grammar:1432:ex2:words:0:pos":"noun","grammar:1432:ex2:words:1:zh":"(topic)","grammar:1432:ex2:words:1:pos":"particle","grammar:1432:ex2:words:2:zh":"sun","grammar:1432:ex2:words:2:note":"たいよう","grammar:1432:ex2:words:2:pos":"noun","grammar:1432:ex2:words:3:zh":"(nominative)","grammar:1432:ex2:words:3:pos":"particle","grammar:1432:ex2:words:4:zh":"extremely","grammar:1432:ex2:words:4:pos":"adverb","grammar:1432:ex2:words:5:zh":"dazzling","grammar:1432:ex2:words:5:note":"まぶしい","grammar:1432:ex2:words:5:pos":"adjective","grammar:1432:ex2:words:6:zh":"(polite form)","grammar:1432:ex2:words:6:pos":"copula","grammar:1432:ex2:points:0":"❗眩しい: dazzling, blinding.","grammar:1432:ex2:points:1":"太陽が眩しい: the sun is dazzling.","grammar:1432:ex3:trans":"The sunlight makes it warm.","grammar:1432:ex3:structure":"〜で暖かくなります","grammar:1432:ex3:words:0:zh":"sun","grammar:1432:ex3:words:0:note":"たいよう","grammar:1432:ex3:words:0:pos":"noun","grammar:1432:ex3:words:1:zh":"'s","grammar:1432:ex3:words:1:pos":"particle","grammar:1432:ex3:words:2:zh":"light","grammar:1432:ex3:words:2:note":"ひかり","grammar:1432:ex3:words:2:pos":"noun","grammar:1432:ex3:words:3:zh":"(cause)","grammar:1432:ex3:words:3:pos":"particle","grammar:1432:ex3:words:4:zh":"get warm","grammar:1432:ex3:words:4:note":"あたたかくなります","grammar:1432:ex3:words:4:pos":"verb","grammar:1432:ex3:points:0":"❗太陽の光: sunlight; 〜で暖かくなる = to get warm from… (「で」 marks cause).","grammar:1432:ex3:points:1":"暖かくなる: to get warm.","grammar:1432:ex4:trans":"The sun goes around the earth.","grammar:1432:ex4:structure":"(the facts are backwards; it should be the earth going around the sun)","grammar:1432:ex4:words:0:zh":"sun","grammar:1432:ex4:words:0:note":"たいよう","grammar:1432:ex4:words:0:pos":"noun","grammar:1432:ex4:words:1:zh":"(topic)","grammar:1432:ex4:words:1:pos":"particle","grammar:1432:ex4:words:2:zh":"the earth","grammar:1432:ex4:words:2:note":"ちきゅう","grammar:1432:ex4:words:2:pos":"noun","grammar:1432:ex4:words:3:zh":"'s","grammar:1432:ex4:words:3:pos":"particle","grammar:1432:ex4:words:4:zh":"surroundings","grammar:1432:ex4:words:4:note":"まわり","grammar:1432:ex4:words:4:pos":"noun","grammar:1432:ex4:words:5:zh":"(path)","grammar:1432:ex4:words:5:pos":"particle","grammar:1432:ex4:words:6:zh":"revolving around","grammar:1432:ex4:words:6:note":"まわっています","grammar:1432:ex4:words:6:pos":"verb","grammar:1432:ex4:points:0":"❗Factually wrong: in reality it's 「地球が太陽の周りを回る」 (the earth goes around the sun); the grammar itself is correct.","grammar:1432:ex4:points:1":"〜の周りを回る: to go around…","grammar:1432:ex5:trans":"I like watching the sun at the seaside.","grammar:1432:ex5:structure":"〜で〜を見るのが好きです","grammar:1432:ex5:words:0:zh":"seaside","grammar:1432:ex5:words:0:note":"うみべ","grammar:1432:ex5:words:0:pos":"noun","grammar:1432:ex5:words:1:zh":"(place)","grammar:1432:ex5:words:1:pos":"particle","grammar:1432:ex5:words:2:zh":"sun","grammar:1432:ex5:words:2:note":"たいよう","grammar:1432:ex5:words:2:pos":"noun","grammar:1432:ex5:words:3:zh":"(object marker)","grammar:1432:ex5:words:3:pos":"particle","grammar:1432:ex5:words:4:zh":"look","grammar:1432:ex5:words:4:note":"みる","grammar:1432:ex5:words:4:pos":"verb","grammar:1432:ex5:words:5:zh":"(nominalizer)","grammar:1432:ex5:words:5:pos":"particle","grammar:1432:ex5:words:6:zh":"(object)","grammar:1432:ex5:words:6:pos":"particle","grammar:1432:ex5:words:7:zh":"to like","grammar:1432:ex5:words:7:note":"すき","grammar:1432:ex5:words:7:pos":"na-adjective","grammar:1432:ex5:words:8:zh":"(polite form)","grammar:1432:ex5:words:8:pos":"copula","grammar:1432:ex5:points:0":"❗海辺で: at the seaside (「で」 marks place); 〜のが好き = to like doing…","grammar:1432:ex5:points:1":"海辺: the seaside."},"1433":{"example:1433:exzh":"I talked it over with a friend and decided.","example:1433:exzh2":"I need to consult my boss.","example:1433:exzh3":"I recommend consulting an expert.","example:1433:exzh4":"May I ask for your advice?","example:1433:exzh5":"He decided after talking it over with his family.","grammar:1433:ex:trans":"I talked it over with a friend and decided.","grammar:1433:ex:structure":"〜と相談して決めました","grammar:1433:ex:explain":"The key here is 「〜と相談する」: 「と」 marks the person you consult, showing that both sides discuss it together, so 「友達と相談する」 means to talk it over with a friend. 「相談して」 is the te-form of 「相談する」, used to connect to the next action and show the order—first discuss, then decide. 「決めました」 is the polite past form of 「決める」. The whole sentence means I talked it over with a friend and then decided, in a polite tone.","grammar:1433:ex:words:0:zh":"friend","grammar:1433:ex:words:0:note":"ともだち","grammar:1433:ex:words:0:pos":"noun","grammar:1433:ex:words:1:zh":"(object)","grammar:1433:ex:words:1:pos":"particle","grammar:1433:ex:words:2:zh":"consultation","grammar:1433:ex:words:2:note":"そうだんして","grammar:1433:ex:words:2:pos":"verb","grammar:1433:ex:words:3:zh":"decided","grammar:1433:ex:words:3:note":"きめました","grammar:1433:ex:words:3:pos":"verb","grammar:1433:ex:points:0":"❗〜と相談する: to discuss with…; 相談 = discussion, consultation.","grammar:1433:ex:points:1":"相談して決める: to discuss and then decide.","grammar:1433:ex2:trans":"I need to consult my boss.","grammar:1433:ex2:structure":"〜に相談する必要があります","grammar:1433:ex2:words:0:zh":"boss","grammar:1433:ex2:words:0:note":"じょうし","grammar:1433:ex2:words:0:pos":"noun","grammar:1433:ex2:words:1:zh":"(object)","grammar:1433:ex2:words:1:pos":"particle","grammar:1433:ex2:words:2:zh":"consultation","grammar:1433:ex2:words:2:note":"そうだんする","grammar:1433:ex2:words:2:pos":"verb","grammar:1433:ex2:words:3:zh":"necessary","grammar:1433:ex2:words:3:note":"ひつよう","grammar:1433:ex2:words:3:pos":"noun","grammar:1433:ex2:words:4:zh":"(nominative)","grammar:1433:ex2:words:4:pos":"particle","grammar:1433:ex2:words:5:zh":"there is / are","grammar:1433:ex2:words:5:pos":"verb","grammar:1433:ex2:points:0":"❗〜に相談する: to consult… (the person takes 「に」); 上司 = boss.","grammar:1433:ex2:points:1":"上司に相談: to consult one's boss.","grammar:1433:ex3:trans":"I recommend that you consult a specialist.","grammar:1433:ex3:structure":"〜することをお勧めします","grammar:1433:ex3:words:0:zh":"expert","grammar:1433:ex3:words:0:note":"せんもんか","grammar:1433:ex3:words:0:pos":"noun","grammar:1433:ex3:words:1:zh":"(object)","grammar:1433:ex3:words:1:pos":"particle","grammar:1433:ex3:words:2:zh":"consultation","grammar:1433:ex3:words:2:note":"そうだんする","grammar:1433:ex3:words:2:pos":"verb","grammar:1433:ex3:words:3:zh":"(nominalizer)","grammar:1433:ex3:words:3:pos":"noun","grammar:1433:ex3:words:4:zh":"(object marker)","grammar:1433:ex3:words:4:pos":"particle","grammar:1433:ex3:words:5:zh":"advice","grammar:1433:ex3:words:5:note":"おすすめします","grammar:1433:ex3:words:5:pos":"verb","grammar:1433:ex3:points:0":"❗〜をお勧めします: I recommend… (humble); 専門家に相談 = to consult a specialist.","grammar:1433:ex3:points:1":"お勧めする: to recommend.","grammar:1433:ex4:trans":"Is it all right if I consult you about something?","grammar:1433:ex4:structure":"〜てもいいですか","grammar:1433:ex4:words:0:zh":"consultation","grammar:1433:ex4:words:0:note":"そうだんして","grammar:1433:ex4:words:0:pos":"verb","grammar:1433:ex4:words:1:zh":"(also)","grammar:1433:ex4:words:1:pos":"particle","grammar:1433:ex4:words:2:zh":"good","grammar:1433:ex4:words:2:note":"いい","grammar:1433:ex4:words:2:pos":"adjective","grammar:1433:ex4:words:3:zh":"(polite form)","grammar:1433:ex4:words:3:pos":"copula","grammar:1433:ex4:words:4:zh":"(question)","grammar:1433:ex4:words:4:pos":"particle","grammar:1433:ex4:points:0":"❗〜てもいいですか: may I …? (permission).","grammar:1433:ex4:points:1":"相談してもいい: it's fine to consult.","grammar:1433:ex5:trans":"He made his decision after discussing it with his family.","grammar:1433:ex5:structure":"〜に相談した後、決めました","grammar:1433:ex5:words:0:zh":"he","grammar:1433:ex5:words:0:note":"かれ","grammar:1433:ex5:words:0:pos":"pronoun","grammar:1433:ex5:words:1:zh":"(topic)","grammar:1433:ex5:words:1:pos":"particle","grammar:1433:ex5:words:2:zh":"family","grammar:1433:ex5:words:2:note":"かぞく","grammar:1433:ex5:words:2:pos":"noun","grammar:1433:ex5:words:3:zh":"(object)","grammar:1433:ex5:words:3:pos":"particle","grammar:1433:ex5:words:4:zh":"discussed","grammar:1433:ex5:words:4:note":"そうだんした","grammar:1433:ex5:words:4:pos":"verb","grammar:1433:ex5:words:5:zh":"later, afterwards","grammar:1433:ex5:words:5:note":"あと","grammar:1433:ex5:words:5:pos":"noun","grammar:1433:ex5:words:6:zh":"decided","grammar:1433:ex5:words:6:note":"きめました","grammar:1433:ex5:words:6:pos":"verb","grammar:1433:ex5:points:0":"❗〜た後: after…; 家族に相談 = to discuss with one's family.","grammar:1433:ex5:points:1":"相談した後: after discussing."},"1434":{"example:1434:exzh":"This service is the worst.","example:1434:exzh2":"It's a movie that got the lowest rating.","example:1434:exzh3":"I signed a contract on the lowest terms.","example:1434:exzh4":"I think his behavior is despicable.","example:1434:exzh5":"It doesn't meet the minimum standard."},"1435":{"example:1435:exzh":"This tape is very strong.","example:1435:exzh2":"I taped up the letter.","example:1435:exzh3":"I'm out of tape, so I'm going to buy some.","example:1435:exzh4":"This tape comes in a wide range of colors.","example:1435:exzh5":"Please seal the box with tape.","grammar:1435:ex:trans":"This tape is very strong.","grammar:1435:ex:structure":"〜はとても強力です","grammar:1435:ex:explain":"This is an adjective-predicate sentence of the form 「〜はとても〜です」. 「強力」 is a na-adjective, and as a predicate it takes 「です」 directly, so 「強力です」 means very strong or sturdy; 「な」 is only added when it modifies a noun (強力なテープ). 「とても」 is an adverb of degree that modifies the following adjective, meaning very. 「テープ」 is a loanword (tape) meaning adhesive tape. The sentence is praising how firmly the tape sticks, in a polite tone.","grammar:1435:ex:words:0:zh":"this","grammar:1435:ex:words:0:pos":"pre-noun adjectival","grammar:1435:ex:words:1:zh":"tape","grammar:1435:ex:words:1:note":"loanword","grammar:1435:ex:words:1:pos":"noun","grammar:1435:ex:words:2:zh":"(topic)","grammar:1435:ex:words:2:pos":"particle","grammar:1435:ex:words:3:zh":"extremely","grammar:1435:ex:words:3:pos":"adverb","grammar:1435:ex:words:4:zh":"strong","grammar:1435:ex:words:4:note":"きょうりょく","grammar:1435:ex:words:4:pos":"na-adjective","grammar:1435:ex:words:5:zh":"(polite form)","grammar:1435:ex:words:5:pos":"copula","grammar:1435:ex:points:0":"❗テープ: tape, adhesive tape (tape); 強力 = strong, sturdy.","grammar:1435:ex:points:1":"強力なテープ: strong tape.","grammar:1435:ex2:trans":"I stuck the letter down with tape.","grammar:1435:ex2:structure":"〜をテープで貼りました","grammar:1435:ex2:words:0:zh":"letter","grammar:1435:ex2:words:0:note":"てがみ","grammar:1435:ex2:words:0:pos":"noun","grammar:1435:ex2:words:1:zh":"(object marker)","grammar:1435:ex2:words:1:pos":"particle","grammar:1435:ex2:words:2:zh":"tape","grammar:1435:ex2:words:2:note":"loanword","grammar:1435:ex2:words:2:pos":"noun","grammar:1435:ex2:words:3:zh":"(means)","grammar:1435:ex2:words:3:pos":"particle","grammar:1435:ex2:words:4:zh":"attached","grammar:1435:ex2:words:4:note":"はりました","grammar:1435:ex2:words:4:pos":"verb","grammar:1435:ex2:points:0":"❗テープで貼る: to stick with tape (「で」 marks means); 貼る = to stick, to paste.","grammar:1435:ex2:points:1":"貼る: to stick.","grammar:1435:ex3:trans":"The tape has run out, so I'm going to buy some.","grammar:1435:ex3:structure":"〜が切れたので〜に行きます","grammar:1435:ex3:words:0:zh":"tape","grammar:1435:ex3:words:0:note":"loanword","grammar:1435:ex3:words:0:pos":"noun","grammar:1435:ex3:words:1:zh":"(nominative)","grammar:1435:ex3:words:1:pos":"particle","grammar:1435:ex3:words:2:zh":"ran out","grammar:1435:ex3:words:2:note":"きれた","grammar:1435:ex3:words:2:pos":"verb","grammar:1435:ex3:words:3:zh":"because","grammar:1435:ex3:words:3:pos":"particle","grammar:1435:ex3:words:4:zh":"buy","grammar:1435:ex3:words:4:note":"かい","grammar:1435:ex3:words:4:pos":"noun","grammar:1435:ex3:words:5:zh":"(purpose)","grammar:1435:ex3:words:5:pos":"particle","grammar:1435:ex3:words:6:zh":"go","grammar:1435:ex3:words:6:pos":"verb","grammar:1435:ex3:points:0":"❗切れる: to run out, to be used up (intransitive verb); 買いに行く = go to buy.","grammar:1435:ex3:points:1":"テープが切れる: the tape runs out.","grammar:1435:ex4:trans":"This tape comes in many colors.","grammar:1435:ex4:structure":"〜は色が豊富です","grammar:1435:ex4:words:0:zh":"this","grammar:1435:ex4:words:0:pos":"pre-noun adjectival","grammar:1435:ex4:words:1:zh":"tape","grammar:1435:ex4:words:1:note":"loanword","grammar:1435:ex4:words:1:pos":"noun","grammar:1435:ex4:words:2:zh":"(topic)","grammar:1435:ex4:words:2:pos":"particle","grammar:1435:ex4:words:3:zh":"color","grammar:1435:ex4:words:3:note":"いろ","grammar:1435:ex4:words:3:pos":"noun","grammar:1435:ex4:words:4:zh":"(nominative)","grammar:1435:ex4:words:4:pos":"particle","grammar:1435:ex4:words:5:zh":"abundant","grammar:1435:ex4:words:5:note":"ほうふ","grammar:1435:ex4:words:5:pos":"na-adjective","grammar:1435:ex4:words:6:zh":"(polite form)","grammar:1435:ex4:words:6:pos":"copula","grammar:1435:ex4:points:0":"❗豊富: abundant, varied; 色が豊富 = available in many colors.","grammar:1435:ex4:points:1":"豊富: abundant.","grammar:1435:ex5:trans":"Please seal the box with tape.","grammar:1435:ex5:structure":"〜で〜を閉じてください","grammar:1435:ex5:words:0:zh":"tape","grammar:1435:ex5:words:0:note":"loanword","grammar:1435:ex5:words:0:pos":"noun","grammar:1435:ex5:words:1:zh":"(means)","grammar:1435:ex5:words:1:pos":"particle","grammar:1435:ex5:words:2:zh":"box","grammar:1435:ex5:words:2:note":"はこ","grammar:1435:ex5:words:2:pos":"noun","grammar:1435:ex5:words:3:zh":"(object marker)","grammar:1435:ex5:words:3:pos":"particle","grammar:1435:ex5:words:4:zh":"seal","grammar:1435:ex5:words:4:note":"とじて","grammar:1435:ex5:words:4:pos":"verb","grammar:1435:ex5:words:5:zh":"please","grammar:1435:ex5:words:5:pos":"auxiliary verb","grammar:1435:ex5:points:0":"❗箱を閉じる: to seal a box (閉じる = to close); テープで = with tape.","grammar:1435:ex5:points:1":"閉じる: to close up, to seal."},"1438":{"example:1438:exzh":"I made a new proposal.","example:1438:exzh2":"I'll present the proposal at the meeting.","example:1438:exzh3":"His proposal was very helpful.","example:1438:exzh4":"You need to prepare when you make a proposal.","example:1438:exzh5":"I prepared a written proposal."},"1440":{"example:1440:exzh":"She is wearing a white dress.","example:1440:exzh2":"I like white flowers.","example:1440:exzh3":"This wall is painted white.","example:1440:exzh4":"I bought white shoes.","example:1440:exzh5":"I love white chocolate."},"1441":{"example:1441:exzh":"He works as a soldier.","example:1441:exzh2":"This soldier is very proud.","example:1441:exzh3":"Soldiers are needed in war.","example:1441:exzh4":"Her father was a soldier in the past.","example:1441:exzh5":"This movie is the story of a soldier."},"1442":{"example:1442:exzh":"You can pay by credit card.","example:1442:exzh2":"The monthly payments are tough.","example:1442:exzh3":"When is this payment due?","example:1442:exzh4":"He forgot to pay.","example:1442:exzh5":"Please keep the receipt for the payment."},"1443":{"example:1443:exzh":"He got his friends involved and played together with them.","example:1443:exzh2":"The people who were caught up in the accident.","example:1443:exzh3":"I don't want to get caught up in that case.","example:1443:exzh4":"What do you do when you get caught up in something?","example:1443:exzh5":"She won't get caught up in the problem."},"1444":{"example:1444:exzh":"I love soba.","example:1444:exzh2":"Let's go eat soba.","example:1444:exzh3":"This soba is really delicious.","example:1444:exzh4":"Boiling soba is easy.","example:1444:exzh5":"The soba broth is delicious too.","grammar:1444:ex:trans":"I love soba.","grammar:1444:ex:structure":"〜が大好きです","grammar:1444:ex:explain":"This sentence uses 「〜が大好きです」 to express a strong liking. Note that in Japanese the thing you like is marked with 「が」, not 「を」, because 「好き」 is grammatically an adjective rather than a verb. 「大好き」 is 「好き」 with 「大」 for emphasis, meaning to like very much, to love. 「そば」 is buckwheat noodles; it sounds the same as 「そば」 meaning beside, so you tell them apart by context. The whole sentence 「そばが大好きです」 means I absolutely love soba.","grammar:1444:ex:words:0:zh":"soba, buckwheat noodles","grammar:1444:ex:words:0:pos":"noun","grammar:1444:ex:words:1:zh":"(object)","grammar:1444:ex:words:1:pos":"particle","grammar:1444:ex:words:2:zh":"love","grammar:1444:ex:words:2:note":"だいすき","grammar:1444:ex:words:2:pos":"na-adjective","grammar:1444:ex:words:3:zh":"(polite form)","grammar:1444:ex:words:3:pos":"copula","grammar:1444:ex:points:1":"そば: soba, buckwheat noodles.","grammar:1444:ex2:trans":"Let's go eat soba.","grammar:1444:ex2:structure":"〜を食べに行きましょう","grammar:1444:ex2:words:0:zh":"soba, buckwheat noodles","grammar:1444:ex2:words:0:pos":"noun","grammar:1444:ex2:words:1:zh":"(object marker)","grammar:1444:ex2:words:1:pos":"particle","grammar:1444:ex2:words:2:zh":"eat","grammar:1444:ex2:words:2:note":"たべ","grammar:1444:ex2:words:2:pos":"noun","grammar:1444:ex2:words:3:zh":"(purpose)","grammar:1444:ex2:words:3:pos":"particle","grammar:1444:ex2:words:4:zh":"let's go","grammar:1444:ex2:words:4:note":"いきましょう","grammar:1444:ex2:words:4:pos":"verb","grammar:1444:ex2:points:0":"❗〜を食べに行く: to go to eat … (masu-form of the verb + に).","grammar:1444:ex2:points:1":"食べに行く: to go to eat.","grammar:1444:ex3:trans":"This soba is very tasty.","grammar:1444:ex3:structure":"〜はとても美味しいです","grammar:1444:ex3:words:0:zh":"this","grammar:1444:ex3:words:0:pos":"pre-noun adjectival","grammar:1444:ex3:words:1:zh":"soba, buckwheat noodles","grammar:1444:ex3:words:1:pos":"noun","grammar:1444:ex3:words:2:zh":"(topic)","grammar:1444:ex3:words:2:pos":"particle","grammar:1444:ex3:words:3:zh":"extremely","grammar:1444:ex3:words:3:pos":"adverb","grammar:1444:ex3:words:4:zh":"delicious","grammar:1444:ex3:words:4:note":"おいしい","grammar:1444:ex3:words:4:pos":"adjective","grammar:1444:ex3:words:5:zh":"(polite form)","grammar:1444:ex3:words:5:pos":"copula","grammar:1444:ex3:points:0":"このそば: this soba.","grammar:1444:ex3:points:1":"美味しい: delicious.","grammar:1444:ex4:trans":"Boiling soba is easy.","grammar:1444:ex4:structure":"〜をゆでるのは簡単です","grammar:1444:ex4:words:0:zh":"soba, buckwheat noodles","grammar:1444:ex4:words:0:pos":"noun","grammar:1444:ex4:words:1:zh":"(object marker)","grammar:1444:ex4:words:1:pos":"particle","grammar:1444:ex4:words:2:zh":"boil","grammar:1444:ex4:words:2:pos":"verb","grammar:1444:ex4:words:3:zh":"(nominalizer)","grammar:1444:ex4:words:3:pos":"particle","grammar:1444:ex4:words:4:zh":"(topic)","grammar:1444:ex4:words:4:pos":"particle","grammar:1444:ex4:words:5:zh":"easy","grammar:1444:ex4:words:5:note":"かんたん","grammar:1444:ex4:words:5:pos":"na-adjective","grammar:1444:ex4:words:6:zh":"(polite form)","grammar:1444:ex4:words:6:pos":"copula","grammar:1444:ex4:points:0":"❗ゆでる: to boil (noodles, eggs, etc.).","grammar:1444:ex4:points:1":"そばをゆでる: to boil soba.","grammar:1444:ex5:trans":"The soba broth is delicious too.","grammar:1444:ex5:structure":"〜の汁もおいしいです","grammar:1444:ex5:words:0:zh":"soba, buckwheat noodles","grammar:1444:ex5:words:0:pos":"noun","grammar:1444:ex5:words:1:zh":"'s","grammar:1444:ex5:words:1:pos":"particle","grammar:1444:ex5:words:2:zh":"broth, sauce","grammar:1444:ex5:words:2:note":"しる","grammar:1444:ex5:words:2:pos":"noun","grammar:1444:ex5:words:3:zh":"also, too","grammar:1444:ex5:words:3:pos":"particle","grammar:1444:ex5:words:4:zh":"tasty","grammar:1444:ex5:words:4:pos":"adjective","grammar:1444:ex5:words:5:zh":"(polite form)","grammar:1444:ex5:words:5:pos":"copula","grammar:1444:ex5:points:0":"❗汁: broth, soup, sauce (そばの汁 = soba dipping sauce or broth).","grammar:1444:ex5:points:1":"汁: broth, soup."},"1445":{"example:1445:exzh":"I threw the ball in the park.","example:1445:exzh2":"Please pick up the ball.","example:1445:exzh3":"I like soccer balls.","example:1445:exzh4":"The kids are playing with a ball.","example:1445:exzh5":"The ball is rolling.","grammar:1445:ex:trans":"I threw a ball in the park.","grammar:1445:ex:structure":"〜で〜を投げました","grammar:1445:ex:explain":"This sentence has two key particles. The 「で」 in 「公園で」 marks where the action takes place = in the park. The 「を」 in 「ボールを」 marks the object of the action, the ball. The verb 「投げる」 means to throw, and 「投げました」 is the polite past form. Be careful to tell 「で」 (where an action happens) apart from 「に」 (where something exists): here the action of playing and throwing takes place in the park, so 「で」 is used. The whole sentence is I threw a ball in the park.","grammar:1445:ex:words:0:zh":"park","grammar:1445:ex:words:0:note":"こうえん","grammar:1445:ex:words:0:pos":"noun","grammar:1445:ex:words:1:zh":"(place)","grammar:1445:ex:words:1:pos":"particle","grammar:1445:ex:words:2:zh":"ball","grammar:1445:ex:words:2:note":"loanword","grammar:1445:ex:words:2:pos":"noun","grammar:1445:ex:words:3:zh":"(object marker)","grammar:1445:ex:words:3:pos":"particle","grammar:1445:ex:words:4:zh":"threw away","grammar:1445:ex:words:4:note":"なげました","grammar:1445:ex:words:4:pos":"verb","grammar:1445:ex:points:0":"❗ボール: a ball (ball); 投げる = to throw; ❓公園で = in the park (で for place).","grammar:1445:ex:points:1":"ボールを投げる: to throw a ball.","grammar:1445:ex2:trans":"Please pick up the ball.","grammar:1445:ex2:structure":"〜を拾ってください","grammar:1445:ex2:words:0:zh":"ball","grammar:1445:ex2:words:0:note":"loanword","grammar:1445:ex2:words:0:pos":"noun","grammar:1445:ex2:words:1:zh":"(object marker)","grammar:1445:ex2:words:1:pos":"particle","grammar:1445:ex2:words:2:zh":"pick up","grammar:1445:ex2:words:2:note":"ひろって","grammar:1445:ex2:words:2:pos":"verb","grammar:1445:ex2:words:3:zh":"please","grammar:1445:ex2:words:3:pos":"auxiliary verb","grammar:1445:ex2:points:0":"❗ボールを拾う: to pick up the ball (拾う = to pick up).","grammar:1445:ex2:points:1":"拾う: to pick up.","grammar:1445:ex3:trans":"I like soccer.","grammar:1445:ex3:structure":"〜のボールが好きです","grammar:1445:ex3:words:0:zh":"soccer","grammar:1445:ex3:words:0:note":"loanword","grammar:1445:ex3:words:0:pos":"noun","grammar:1445:ex3:words:1:zh":"'s","grammar:1445:ex3:words:1:pos":"particle","grammar:1445:ex3:words:2:zh":"ball","grammar:1445:ex3:words:2:note":"loanword","grammar:1445:ex3:words:2:pos":"noun","grammar:1445:ex3:words:3:zh":"(object)","grammar:1445:ex3:words:3:pos":"particle","grammar:1445:ex3:words:4:zh":"to like","grammar:1445:ex3:words:4:note":"すき","grammar:1445:ex3:words:4:pos":"na-adjective","grammar:1445:ex3:words:5:zh":"(polite form)","grammar:1445:ex3:words:5:pos":"copula","grammar:1445:ex3:points:0":"❗サッカーのボール: a soccer ball (the ball itself).","grammar:1445:ex3:points:1":"〜が好き: to like …","grammar:1445:ex4:trans":"The children are playing with a ball.","grammar:1445:ex4:structure":"〜で遊んでいます","grammar:1445:ex4:words:0:zh":"children","grammar:1445:ex4:words:0:note":"こどもたち","grammar:1445:ex4:words:0:pos":"noun","grammar:1445:ex4:words:1:zh":"(nominative)","grammar:1445:ex4:words:1:pos":"particle","grammar:1445:ex4:words:2:zh":"ball","grammar:1445:ex4:words:2:note":"loanword","grammar:1445:ex4:words:2:pos":"noun","grammar:1445:ex4:words:3:zh":"(means)","grammar:1445:ex4:words:3:pos":"particle","grammar:1445:ex4:words:4:zh":"are playing","grammar:1445:ex4:words:4:note":"あそんでいます","grammar:1445:ex4:words:4:pos":"verb","grammar:1445:ex4:points:0":"❗ボールで遊ぶ: to play with a ball (で for means); 子供たち = children.","grammar:1445:ex4:points:1":"ボールで遊ぶ: to play with a ball.","grammar:1445:ex5:trans":"The ball is rolling.","grammar:1445:ex5:structure":"〜が転がっています","grammar:1445:ex5:words:0:zh":"ball","grammar:1445:ex5:words:0:note":"loanword","grammar:1445:ex5:words:0:pos":"noun","grammar:1445:ex5:words:1:zh":"(nominative)","grammar:1445:ex5:words:1:pos":"particle","grammar:1445:ex5:words:2:zh":"is rolling","grammar:1445:ex5:words:2:note":"ころがっています","grammar:1445:ex5:words:2:pos":"verb","grammar:1445:ex5:points:0":"❗転がる: to roll (intransitive verb).","grammar:1445:ex5:points:1":"ボールが転がる: the ball rolls."},"1446":{"example:1446:exzh":"The robot cleans for me.","example:1446:exzh2":"This robot can talk.","example:1446:exzh3":"I watched a robot movie.","example:1446:exzh4":"He's good at making robots.","example:1446:exzh5":"Robot technology is advancing.","grammar:1446:ex:trans":"The robot cleans for me.","grammar:1446:ex:structure":"〜が〜てくれます","grammar:1446:ex:explain":"The core of this sentence is the auxiliary pattern 「〜てくれる」, which shows that someone does something for me or for my side, with a nuance of gratitude and benefit. 「掃除して」 is the te-form of 「掃除する」, and adding 「くれます」 gives the robot cleans for me. The subject 「ロボット」 is marked with 「が」 as the one doing the action. This 「くれる」 takes the speaker's viewpoint and emphasizes that the other party's action benefits me. The whole sentence is the robot does the cleaning for me.","grammar:1446:ex:words:0:zh":"robot","grammar:1446:ex:words:0:note":"loanword","grammar:1446:ex:words:0:pos":"noun","grammar:1446:ex:words:1:zh":"(nominative)","grammar:1446:ex:words:1:pos":"particle","grammar:1446:ex:words:2:zh":"cleaning","grammar:1446:ex:words:2:note":"そうじして","grammar:1446:ex:words:2:pos":"verb","grammar:1446:ex:words:3:zh":"makes (for me)","grammar:1446:ex:words:3:pos":"auxiliary verb","grammar:1446:ex:points:0":"❗ロボット: a robot (robot); 〜てくれる = to do … (for me).","grammar:1446:ex:points:1":"掃除してくれる: to clean for me.","grammar:1446:ex2:trans":"This robot can talk.","grammar:1446:ex2:structure":"〜は話せます","grammar:1446:ex2:words:0:zh":"this","grammar:1446:ex2:words:0:pos":"pre-noun adjectival","grammar:1446:ex2:words:1:zh":"robot","grammar:1446:ex2:words:1:note":"loanword","grammar:1446:ex2:words:1:pos":"noun","grammar:1446:ex2:words:2:zh":"(topic)","grammar:1446:ex2:words:2:pos":"particle","grammar:1446:ex2:words:3:zh":"can talk","grammar:1446:ex2:words:3:note":"はなせます","grammar:1446:ex2:words:3:pos":"verb","grammar:1446:ex2:points:0":"❗話せる: to be able to speak (the potential form of 話す).","grammar:1446:ex2:points:1":"話せる: to be able to talk.","grammar:1446:ex3:trans":"I watched a robot movie.","grammar:1446:ex3:structure":"〜を見ました","grammar:1446:ex3:words:0:zh":"robot movie","grammar:1446:ex3:words:0:note":"ロボットえいが","grammar:1446:ex3:words:0:pos":"noun","grammar:1446:ex3:words:1:zh":"(object marker)","grammar:1446:ex3:words:1:pos":"particle","grammar:1446:ex3:words:2:zh":"watched","grammar:1446:ex3:words:2:note":"みました","grammar:1446:ex3:words:2:pos":"verb","grammar:1446:ex3:points:0":"❗ロボット映画: a movie about robots.","grammar:1446:ex3:points:1":"映画を見る: to watch a movie.","grammar:1446:ex4:trans":"He is good at making robots.","grammar:1446:ex4:structure":"〜を作るのが得意です","grammar:1446:ex4:words:0:zh":"he","grammar:1446:ex4:words:0:note":"かれ","grammar:1446:ex4:words:0:pos":"pronoun","grammar:1446:ex4:words:1:zh":"(topic)","grammar:1446:ex4:words:1:pos":"particle","grammar:1446:ex4:words:2:zh":"robot","grammar:1446:ex4:words:2:note":"loanword","grammar:1446:ex4:words:2:pos":"noun","grammar:1446:ex4:words:3:zh":"(object marker)","grammar:1446:ex4:words:3:pos":"particle","grammar:1446:ex4:words:4:zh":"making","grammar:1446:ex4:words:4:note":"つくる","grammar:1446:ex4:words:4:pos":"verb","grammar:1446:ex4:words:5:zh":"(nominalizer)","grammar:1446:ex4:words:5:pos":"particle","grammar:1446:ex4:words:6:zh":"(object)","grammar:1446:ex4:words:6:pos":"particle","grammar:1446:ex4:words:7:zh":"good at","grammar:1446:ex4:words:7:note":"とくい","grammar:1446:ex4:words:7:pos":"na-adjective","grammar:1446:ex4:words:8:zh":"(polite form)","grammar:1446:ex4:words:8:pos":"copula","grammar:1446:ex4:points:0":"❗〜のが得意: to be good at doing …; ロボットを作る = to make robots.","grammar:1446:ex4:points:1":"得意: good at.","grammar:1446:ex5:trans":"Robot technology is advancing.","grammar:1446:ex5:structure":"〜の技術が進歩しています","grammar:1446:ex5:words:0:zh":"robot","grammar:1446:ex5:words:0:note":"loanword","grammar:1446:ex5:words:0:pos":"noun","grammar:1446:ex5:words:1:zh":"'s","grammar:1446:ex5:words:1:pos":"particle","grammar:1446:ex5:words:2:zh":"technology","grammar:1446:ex5:words:2:note":"ぎじゅつ","grammar:1446:ex5:words:2:pos":"noun","grammar:1446:ex5:words:3:zh":"(nominative)","grammar:1446:ex5:words:3:pos":"particle","grammar:1446:ex5:words:4:zh":"is improving","grammar:1446:ex5:words:4:note":"しんぽしています","grammar:1446:ex5:words:4:pos":"verb","grammar:1446:ex5:points:0":"❗進歩する: to advance, to progress; ロボットの技術 = robot technology.","grammar:1446:ex5:points:1":"技術が進歩: the technology advances."},"1447":{"example:1447:exzh":"This warehouse is big.","example:1447:exzh2":"This is a warehouse for storing things.","example:1447:exzh3":"I'm going to the warehouse.","example:1447:exzh4":"What is this warehouse for?","example:1447:exzh5":"We're building a new warehouse."},"1448":{"example:1448:exzh":"This fan is powerful.","example:1448:exzh2":"He's a fan of that artist.","example:1448:exzh3":"It has a lot of fans.","example:1448:exzh4":"I'll take photos of the fans.","example:1448:exzh5":"It's hot, so please turn on the fan."},"1449":{"example:1449:exzh":"It's important to be considerate of others.","example:1449:exzh2":"He is helping others.","example:1449:exzh3":"Let's respect other people's opinions.","example:1449:exzh4":"This problem affects other people too.","example:1449:exzh5":"I need other people's help."},"1450":{"example:1450:exzh":"He is the hero of the town.","example:1450:exzh2":"I like stories about heroes.","example:1450:exzh3":"She took heroic action.","example:1450:exzh4":"The main character of this movie is a hero.","example:1450:exzh5":"Heroes have a lot of suffering."},"1451":{"example:1451:exzh":"I invited my friends.","example:1451:exzh2":"I was invited to a party.","example:1451:exzh3":"I forgot to invite him.","example:1451:exzh4":"I'll send the invitation.","example:1451:exzh5":"She invited her family."},"1452":{"example:1452:exzh":"Medical care is advancing.","example:1452:exzh2":"Are you enrolled in health insurance?","example:1452:exzh3":"He is a healthcare worker.","example:1452:exzh4":"I think about issues related to healthcare.","example:1452:exzh5":"A healthcare system is necessary."},"1453":{"example:1453:exzh":"I'll find a reliable method.","example:1453:exzh2":"The result is certain.","example:1453:exzh3":"His success is certain.","example:1453:exzh4":"It's important to act with certainty.","example:1453:exzh5":"I'll gather reliable information."},"1454":{"example:1454:exzh":"He was released.","example:1454:exzh2":"The release procedures are required.","example:1454:exzh3":"An unjust release is not acceptable.","example:1454:exzh4":"I'll explain the reason he was released.","example:1454:exzh5":"Demand her release."},"1455":{"example:1455:exzh":"The shinkansen is a type of train.","example:1455:exzh2":"The train is running late.","example:1455:exzh3":"He commutes by train.","example:1455:exzh4":"Check the train timetable.","example:1455:exzh5":"I missed the train.","grammar:1455:ex:trans":"The Shinkansen is a type of train.","grammar:1455:ex:structure":"〜は〜の一つです","grammar:1455:ex:explain":"This sentence uses 「〜の一つ」 to mean one of a group. 「列車の一つ」 = a type of train, one member of the many trains. 「新幹線は」 uses 「は」 to present the topic, and 「の」 links 「列車」 and 「一つ」. The ending 「です」 states a judgment. This is a very useful classification pattern for saying that something is one item within a category. The whole sentence 「新幹線は列車の一つです」 means the Shinkansen is a type of train.","grammar:1455:ex:words:0:zh":"Shinkansen","grammar:1455:ex:words:0:note":"しんかんせん","grammar:1455:ex:words:0:pos":"noun","grammar:1455:ex:words:1:zh":"(topic)","grammar:1455:ex:words:1:pos":"particle","grammar:1455:ex:words:2:zh":"train","grammar:1455:ex:words:2:note":"れっしゃ","grammar:1455:ex:words:2:pos":"noun","grammar:1455:ex:words:3:zh":"'s","grammar:1455:ex:words:3:pos":"particle","grammar:1455:ex:words:4:zh":"one kind, one of","grammar:1455:ex:words:4:note":"ひとつ","grammar:1455:ex:words:4:pos":"noun","grammar:1455:ex:words:5:zh":"is","grammar:1455:ex:words:5:pos":"copula","grammar:1455:ex:points:0":"❗列車（れっしゃ）: train; 新幹線 = Shinkansen; 〜の一つ = one of ….","grammar:1455:ex:points:1":"列車の一つ: one of the trains.","grammar:1455:ex2:trans":"The train is delayed.","grammar:1455:ex2:structure":"〜が遅れています","grammar:1455:ex2:words:0:zh":"train","grammar:1455:ex2:words:0:note":"れっしゃ","grammar:1455:ex2:words:0:pos":"noun","grammar:1455:ex2:words:1:zh":"(nominative)","grammar:1455:ex2:words:1:pos":"particle","grammar:1455:ex2:words:2:zh":"is delayed","grammar:1455:ex2:words:2:note":"おくれています","grammar:1455:ex2:words:2:pos":"verb","grammar:1455:ex2:points:0":"❗遅れる: to be delayed, to run late (intransitive verb).","grammar:1455:ex2:points:1":"列車が遅れる: the train runs late.","grammar:1455:ex3:trans":"He commutes by train.","grammar:1455:ex3:structure":"〜で通勤します","grammar:1455:ex3:words:0:zh":"he","grammar:1455:ex3:words:0:note":"かれ","grammar:1455:ex3:words:0:pos":"pronoun","grammar:1455:ex3:words:1:zh":"(topic)","grammar:1455:ex3:words:1:pos":"particle","grammar:1455:ex3:words:2:zh":"train","grammar:1455:ex3:words:2:note":"れっしゃ","grammar:1455:ex3:words:2:pos":"noun","grammar:1455:ex3:words:3:zh":"(means)","grammar:1455:ex3:words:3:pos":"particle","grammar:1455:ex3:words:4:zh":"commute","grammar:1455:ex3:words:4:note":"つうきんします","grammar:1455:ex3:words:4:pos":"verb","grammar:1455:ex3:points:0":"❗〜で通勤する: commute by … (で marks the means); 通勤 = commuting to and from work.","grammar:1455:ex3:points:1":"列車で通勤: commute by train.","grammar:1455:ex4:trans":"Check the train timetable.","grammar:1455:ex4:structure":"〜の時刻表を調べる","grammar:1455:ex4:words:0:zh":"train","grammar:1455:ex4:words:0:note":"れっしゃ","grammar:1455:ex4:words:0:pos":"noun","grammar:1455:ex4:words:1:zh":"'s","grammar:1455:ex4:words:1:pos":"particle","grammar:1455:ex4:words:2:zh":"timetable","grammar:1455:ex4:words:2:note":"じこくひょう","grammar:1455:ex4:words:2:pos":"noun","grammar:1455:ex4:words:3:zh":"(object marker)","grammar:1455:ex4:words:3:pos":"particle","grammar:1455:ex4:words:4:zh":"look up","grammar:1455:ex4:words:4:note":"しらべる","grammar:1455:ex4:words:4:pos":"verb","grammar:1455:ex4:points:0":"❗時刻表: timetable (時刻 + 表); 調べる = to look up.","grammar:1455:ex4:points:1":"時刻表を調べる: check the timetable.","grammar:1455:ex5:trans":"Missed the train.","grammar:1455:ex5:structure":"〜に乗り遅れた","grammar:1455:ex5:words:0:zh":"train","grammar:1455:ex5:words:0:note":"れっしゃ","grammar:1455:ex5:words:0:pos":"noun","grammar:1455:ex5:words:1:zh":"(what you ride)","grammar:1455:ex5:words:1:pos":"particle","grammar:1455:ex5:words:2:zh":"missed (a train)","grammar:1455:ex5:words:2:note":"のりおくれた","grammar:1455:ex5:words:2:pos":"verb","grammar:1455:ex5:points:0":"❗〜に乗り遅れる: to miss (a train) (乗る + 遅れる).","grammar:1455:ex5:points:1":"列車に乗り遅れる: miss the train."},"1456":{"example:1456:exzh":"It's hard to persuade him.","example:1456:exzh2":"Tell a persuasive story.","example:1456:exzh3":"She was persuaded.","example:1456:exzh4":"Persuasion is sometimes necessary.","example:1456:exzh5":"He's good at persuading people."},"1457":{"example:1457:exzh":"Once winter comes, there are more cold days.","example:1457:exzh2":"When it's cold, you feel like drinking something warm.","example:1457:exzh3":"She lives in a cold place.","example:1457:exzh4":"As soon as I stepped outside, I felt a cold wind blowing.","example:1457:exzh5":"I can't stand the cold, so I leave the heater on the whole time.","grammar:1457:ex:trans":"When winter comes, there are more cold days.","grammar:1457:ex:structure":"〜になると〜が多くなります","grammar:1457:ex:explain":"This sentence has two key points. In 「冬になると」, 「〜と」 marks a natural condition — whenever X happens, Y follows — and it attaches to the plain form; 「冬になると」 = whenever winter comes. 「寒い日が多くなります」 uses 「〜くなる」 to show change: the i-adjective 「多い」 changes its final い to く and adds 「なる」, so 「多くなる」 = to increase. The whole sentence means that once winter comes, the cold days increase, describing an inevitable seasonal phenomenon.","grammar:1457:ex:words:0:zh":"winter","grammar:1457:ex:words:0:note":"ふゆ","grammar:1457:ex:words:0:pos":"noun","grammar:1457:ex:words:1:zh":"(result)","grammar:1457:ex:words:1:pos":"particle","grammar:1457:ex:words:2:zh":"become","grammar:1457:ex:words:2:pos":"verb","grammar:1457:ex:words:3:zh":"(as soon as…)","grammar:1457:ex:words:3:pos":"particle","grammar:1457:ex:words:4:zh":"cold","grammar:1457:ex:words:4:note":"さむい","grammar:1457:ex:words:4:pos":"adjective","grammar:1457:ex:words:5:zh":"day","grammar:1457:ex:words:5:note":"ひ","grammar:1457:ex:words:5:pos":"noun","grammar:1457:ex:words:6:zh":"(nominative)","grammar:1457:ex:words:6:pos":"particle","grammar:1457:ex:words:7:zh":"become more","grammar:1457:ex:words:7:note":"おおくなります","grammar:1457:ex:words:7:pos":"verb","grammar:1457:ex:points:0":"❗寒い（さむい）: cold; 〜になると = whenever … happens; 〜くなる = become ….","grammar:1457:ex:points:1":"冬になると: when winter comes.","grammar:1457:ex2:trans":"When it's cold, you want to drink something warm.","grammar:1457:ex2:structure":"寒い時は〜が飲みたくなります","grammar:1457:ex2:words:0:zh":"cold","grammar:1457:ex2:words:0:note":"さむい","grammar:1457:ex2:words:0:pos":"adjective","grammar:1457:ex2:words:1:zh":"time","grammar:1457:ex2:words:1:note":"とき","grammar:1457:ex2:words:1:pos":"noun","grammar:1457:ex2:words:2:zh":"(topic)","grammar:1457:ex2:words:2:pos":"particle","grammar:1457:ex2:words:3:zh":"warm","grammar:1457:ex2:words:3:note":"あたたかい","grammar:1457:ex2:words:3:pos":"adjective","grammar:1457:ex2:words:4:zh":"drink","grammar:1457:ex2:words:4:note":"のみもの","grammar:1457:ex2:words:4:pos":"noun","grammar:1457:ex2:words:5:zh":"(object)","grammar:1457:ex2:words:5:pos":"particle","grammar:1457:ex2:words:6:zh":"come to want to drink","grammar:1457:ex2:words:6:note":"のみたくなります","grammar:1457:ex2:words:6:pos":"verb","grammar:1457:ex2:points:0":"❗〜たくなる: come to want to … (飲みたい + なる); 温かい飲み物 = a warm drink.","grammar:1457:ex2:points:1":"飲みたくなる: to want to drink.","grammar:1457:ex3:trans":"She lives in a cold place.","grammar:1457:ex3:structure":"寒い〜に住んでいます","grammar:1457:ex3:words:0:zh":"she","grammar:1457:ex3:words:0:note":"かのじょ","grammar:1457:ex3:words:0:pos":"pronoun","grammar:1457:ex3:words:1:zh":"(topic)","grammar:1457:ex3:words:1:pos":"particle","grammar:1457:ex3:words:2:zh":"cold","grammar:1457:ex3:words:2:note":"さむい","grammar:1457:ex3:words:2:pos":"adjective","grammar:1457:ex3:words:3:zh":"place","grammar:1457:ex3:words:3:note":"ちほう","grammar:1457:ex3:words:3:pos":"noun","grammar:1457:ex3:words:4:zh":"(place of residence)","grammar:1457:ex3:words:4:pos":"particle","grammar:1457:ex3:words:5:zh":"are living","grammar:1457:ex3:words:5:note":"すんでいます","grammar:1457:ex3:words:5:pos":"verb","grammar:1457:ex3:points:0":"❗寒い地方: a cold region; 〜に住む = to live in ….","grammar:1457:ex3:points:1":"寒い地方: a cold region.","grammar:1457:ex4:trans":"The moment you step outside, a cold wind is blowing.","grammar:1457:ex4:structure":"〜に出ると〜が吹いています","grammar:1457:ex4:words:0:zh":"outside","grammar:1457:ex4:words:0:note":"そと","grammar:1457:ex4:words:0:pos":"noun","grammar:1457:ex4:words:1:zh":"(the destination point)","grammar:1457:ex4:words:1:pos":"particle","grammar:1457:ex4:words:2:zh":"go out","grammar:1457:ex4:words:2:note":"でる","grammar:1457:ex4:words:2:pos":"verb","grammar:1457:ex4:words:3:zh":"(as soon as…)","grammar:1457:ex4:words:3:pos":"particle","grammar:1457:ex4:words:4:zh":"cold","grammar:1457:ex4:words:4:note":"さむい","grammar:1457:ex4:words:4:pos":"adjective","grammar:1457:ex4:words:5:zh":"wind","grammar:1457:ex4:words:5:note":"かぜ","grammar:1457:ex4:words:5:pos":"noun","grammar:1457:ex4:words:6:zh":"(nominative)","grammar:1457:ex4:words:6:pos":"particle","grammar:1457:ex4:words:7:zh":"is blowing","grammar:1457:ex4:words:7:note":"ふいています","grammar:1457:ex4:words:7:pos":"verb","grammar:1457:ex4:points:0":"❗〜と: whenever … then …; 風が吹く = the wind blows.","grammar:1457:ex4:points:1":"寒い風: a cold wind.","grammar:1457:ex5:trans":"I can't stand the cold, so I leave the heater on all the time.","grammar:1457:ex5:structure":"〜のが苦手な私は、〜をつけっぱなしにします","grammar:1457:ex5:explain":"「寒いのが苦手な」 modifies 「私」 as a whole, meaning the me who can't handle the cold. 「暖房をつける」 means to turn on the heating; 「つけっぱなし」 means leaving it on and never turning it off. 「にします」 shows deliberately keeping the heater in that state.","grammar:1457:ex5:words:0:zh":"cold","grammar:1457:ex5:words:0:note":"さむい","grammar:1457:ex5:words:0:pos":"i-adjective","grammar:1457:ex5:words:1:zh":"(nominalizer)","grammar:1457:ex5:words:1:pos":"particle","grammar:1457:ex5:words:2:zh":"(the thing one can't handle)","grammar:1457:ex5:words:2:pos":"particle","grammar:1457:ex5:words:3:zh":"not good with, can't stand","grammar:1457:ex5:words:3:note":"にがて","grammar:1457:ex5:words:3:pos":"na-adjective","grammar:1457:ex5:words:4:zh":"(links a na-adjective to a noun)","grammar:1457:ex5:words:4:pos":"auxiliary verb","grammar:1457:ex5:words:5:zh":"I","grammar:1457:ex5:words:5:note":"わたし","grammar:1457:ex5:words:5:pos":"pronoun","grammar:1457:ex5:words:6:zh":"(topic)","grammar:1457:ex5:words:6:pos":"particle","grammar:1457:ex5:words:7:zh":"heating","grammar:1457:ex5:words:7:note":"だんぼう","grammar:1457:ex5:words:7:pos":"noun","grammar:1457:ex5:words:8:zh":"(object)","grammar:1457:ex5:words:8:pos":"particle","grammar:1457:ex5:words:9:zh":"turn on","grammar:1457:ex5:words:9:pos":"verb","grammar:1457:ex5:words:10:zh":"leave as is","grammar:1457:ex5:words:10:pos":"suffix","grammar:1457:ex5:words:11:zh":"(the state it is set to)","grammar:1457:ex5:words:11:pos":"particle","grammar:1457:ex5:words:12:zh":"make, keep","grammar:1457:ex5:words:12:pos":"verb","grammar:1457:ex5:words:13:zh":"(polite ending)","grammar:1457:ex5:words:13:pos":"auxiliary verb","grammar:1457:ex5:points:0":"「寒いの」 uses 「の」 to nominalize the adjective, referring to being cold.","grammar:1457:ex5:points:1":"「苦手な私」 uses 「な」 to connect the na-adjective to the noun.","grammar:1457:ex5:points:2":"Verb masu-form minus ます + っぱなし means the state continues after the action, often with a nuance of something left unattended.","exam:1457:zh":"It's very cold today, so even with a coat on, my body still feels cold.","exam:1457:why":"Still feeling cold even in a coat fits 「寒い」. 「涼しい」 means cool and usually isn't cold enough to need a coat against it."},"1458":{"example:1458:exzh":"This project is being carried forward based on instructions from headquarters.","example:1458:exzh2":"The new headquarters is in the city center.","example:1458:exzh3":"The headquarters meeting will be held next Monday.","example:1458:exzh4":"He plays an important role at headquarters.","example:1458:exzh5":"I'm waiting to hear from headquarters."},"1459":{"example:1459:exzh":"Do you have wireless internet at home?","example:1459:exzh2":"Wireless communication is convenient, but you need to be careful about security.","example:1459:exzh3":"He has a wireless radio.","example:1459:exzh4":"Wireless technology is evolving rapidly.","example:1459:exzh5":"If you use wireless devices, you don't need any wiring."},"1460":{"example:1460:exzh":"Babies need a lot of sleep.","example:1460:exzh2":"She was holding a baby.","example:1460:exzh3":"The baby can't talk yet.","example:1460:exzh4":"A baby's smile is so comforting.","example:1460:exzh5":"The baby saw its first winter."},"1461":{"example:1461:exzh":"He's good at pulling weeds.","example:1461:exzh2":"He pulled out a pencil and started writing.","example:1461:exzh3":"If you pull out this plug, water comes out.","example:1461:exzh4":"It's not good to pull flowers from the garden.","example:1461:exzh5":"Pulling out a big tree isn't easy."},"1462":{"example:1462:exzh":"Getting together with friends is fun.","example:1462:exzh2":"There are often events in places where people gather.","example:1462:exzh3":"We gathered at the sports club.","example:1462:exzh4":"Let's all get together and celebrate.","example:1462:exzh5":"Everyone needs to gather for the meeting.","grammar:1462:ex:trans":"It's fun when friends get together.","grammar:1462:ex:structure":"〜が集まると楽しいです","grammar:1462:ex:explain":"This sentence contrasts a transitive and an intransitive verb and uses 「〜と」 for a condition. 「集まる」 is an intransitive verb (people gather on their own), so its subject takes 「が」; don't confuse it with the transitive 「集める」 (to collect things, taking を). The 「〜と」 in 「友達が集まると」 means whenever X happens, Y follows, attaches to the plain form, and describes an inevitable result. 「楽しい」 is an i-adjective plus 「です」. The whole sentence means it's fun whenever friends get together.","grammar:1462:ex:words:0:zh":"friend","grammar:1462:ex:words:0:note":"ともだち","grammar:1462:ex:words:0:pos":"noun","grammar:1462:ex:words:1:zh":"(nominative)","grammar:1462:ex:words:1:pos":"particle","grammar:1462:ex:words:2:zh":"gather","grammar:1462:ex:words:2:note":"あつまる","grammar:1462:ex:words:2:pos":"verb","grammar:1462:ex:words:3:zh":"(as soon as…)","grammar:1462:ex:words:3:pos":"particle","grammar:1462:ex:words:4:zh":"happy","grammar:1462:ex:words:4:note":"たのしい","grammar:1462:ex:words:4:pos":"adjective","grammar:1462:ex:words:5:zh":"(polite form)","grammar:1462:ex:words:5:pos":"copula","grammar:1462:ex:points:0":"❗集まる (intransitive verb, to gather) + が; vs 集める (transitive verb, to collect); 〜と = whenever … then ….","grammar:1462:ex:points:1":"友達が集まる: friends gather.","grammar:1462:ex2:trans":"Places where a lot of people gather often have events.","grammar:1462:ex2:structure":"〜が集まる所には〜があります","grammar:1462:ex2:words:0:zh":"person","grammar:1462:ex2:words:0:note":"ひと","grammar:1462:ex2:words:0:pos":"noun","grammar:1462:ex2:words:1:zh":"(nominative)","grammar:1462:ex2:words:1:pos":"particle","grammar:1462:ex2:words:2:zh":"gather","grammar:1462:ex2:words:2:note":"あつまる","grammar:1462:ex2:words:2:pos":"verb","grammar:1462:ex2:words:3:zh":"place","grammar:1462:ex2:words:3:note":"ところ","grammar:1462:ex2:words:3:pos":"noun","grammar:1462:ex2:words:4:zh":"(location of existence)","grammar:1462:ex2:words:4:pos":"particle","grammar:1462:ex2:words:5:zh":"(contrast)","grammar:1462:ex2:words:5:pos":"particle","grammar:1462:ex2:words:6:zh":"often","grammar:1462:ex2:words:6:pos":"adverb","grammar:1462:ex2:words:7:zh":"event","grammar:1462:ex2:words:7:note":"loanword","grammar:1462:ex2:words:7:pos":"noun","grammar:1462:ex2:words:8:zh":"(nominative)","grammar:1462:ex2:words:8:pos":"particle","grammar:1462:ex2:words:9:zh":"there is / are","grammar:1462:ex2:words:9:pos":"verb","grammar:1462:ex2:points:0":"❗人が集まる所: a place where people gather (attributive); よく = often.","grammar:1462:ex2:points:1":"集まる所: a gathering place.","grammar:1462:ex3:trans":"We gathered at the sports club.","grammar:1462:ex3:structure":"〜に集まりました","grammar:1462:ex3:words:0:zh":"sports club","grammar:1462:ex3:words:0:note":"loanword","grammar:1462:ex3:words:0:pos":"noun","grammar:1462:ex3:words:1:zh":"(result)","grammar:1462:ex3:words:1:pos":"particle","grammar:1462:ex3:words:2:zh":"gathered","grammar:1462:ex3:words:2:note":"あつまりました","grammar:1462:ex3:words:2:pos":"verb","grammar:1462:ex3:points:0":"❗〜に集まる: to gather at … (に marks the target); スポーツクラブ = sports club.","grammar:1462:ex3:points:1":"集まる: to gather.","grammar:1462:ex4:trans":"Let's all get together and celebrate.","grammar:1462:ex4:structure":"皆で集まって〜しましょう","grammar:1462:ex4:words:0:zh":"everyone","grammar:1462:ex4:words:0:note":"みんな","grammar:1462:ex4:words:0:pos":"pronoun","grammar:1462:ex4:words:1:zh":"(a state)","grammar:1462:ex4:words:1:pos":"particle","grammar:1462:ex4:words:2:zh":"gather","grammar:1462:ex4:words:2:note":"あつまって","grammar:1462:ex4:words:2:pos":"verb","grammar:1462:ex4:words:3:zh":"let's celebrate","grammar:1462:ex4:words:3:note":"おいわいしましょう","grammar:1462:ex4:words:3:pos":"verb","grammar:1462:ex4:points:0":"❗皆で集まる: everyone gathers together (で marks the group); お祝いする = to celebrate.","grammar:1462:ex4:points:1":"皆で集まる: to gather together.","grammar:1462:ex5:trans":"Everyone needs to gather for the meeting.","grammar:1462:ex5:structure":"〜には〜が集まる必要があります","grammar:1462:ex5:words:0:zh":"meeting","grammar:1462:ex5:words:0:note":"かいぎ","grammar:1462:ex5:words:0:pos":"noun","grammar:1462:ex5:words:1:zh":"(object)","grammar:1462:ex5:words:1:pos":"particle","grammar:1462:ex5:words:2:zh":"(contrast)","grammar:1462:ex5:words:2:pos":"particle","grammar:1462:ex5:words:3:zh":"all members","grammar:1462:ex5:words:3:note":"ぜんいん","grammar:1462:ex5:words:3:pos":"noun","grammar:1462:ex5:words:4:zh":"(nominative)","grammar:1462:ex5:words:4:pos":"particle","grammar:1462:ex5:words:5:zh":"gather","grammar:1462:ex5:words:5:note":"あつまる","grammar:1462:ex5:words:5:pos":"verb","grammar:1462:ex5:words:6:zh":"necessary","grammar:1462:ex5:words:6:note":"ひつよう","grammar:1462:ex5:words:6:pos":"noun","grammar:1462:ex5:words:7:zh":"(nominative)","grammar:1462:ex5:words:7:pos":"particle","grammar:1462:ex5:words:8:zh":"there is / are","grammar:1462:ex5:words:8:pos":"verb","grammar:1462:ex5:points:0":"❗全員が集まる: everyone is present; 〜必要があります = it is necessary to…","grammar:1462:ex5:points:1":"全員: everyone."},"1463":{"example:1463:exzh":"He's in the soccer group.","example:1463:exzh2":"There are three groups in my class.","example:1463:exzh3":"She's active in the dance group.","example:1463:exzh4":"Deciding on a group name is fun.","example:1463:exzh5":"There's an event where the groups compete against each other."},"1464":{"example:1464:exzh":"Laws are important for protecting society.","example:1464:exzh2":"Japanese laws are strict.","example:1464:exzh3":"He is studying law.","example:1464:exzh4":"Knowledge of the law is useful.","example:1464:exzh5":"The new law has taken effect."},"1465":{"example:1465:exzh":"Repeating the same thing is a waste.","example:1465:exzh2":"She sang that song over and over.","example:1465:exzh3":"You improve by repeating this practice.","example:1465:exzh4":"Repetitive study is important.","example:1465:exzh5":"Let's try not to repeat the same mistakes."},"1466":{"example:1466:exzh":"His habits can sometimes annoy people.","example:1466:exzh2":"That habit is hard to break.","example:1466:exzh3":"She has a unique habit.","example:1466:exzh4":"Everyone has their own habits.","example:1466:exzh5":"I want to break this habit."},"1467":{"example:1467:exzh":"That music is too loud.","example:1467:exzh2":"There's a very noisy neighbor.","example:1467:exzh3":"He's so loud that I can't concentrate.","example:1467:exzh4":"Please don't be so loud.","example:1467:exzh5":"This place is quiet and not noisy.","grammar:1467:ex:trans":"That music is too loud.","grammar:1467:ex:structure":"〜はうるさすぎる","grammar:1467:ex:explain":"The core of this sentence is 「〜すぎる」, which means too much, excessively. It attaches to an adjective stem or to a verb masu-form; here 「うるさい」 drops い and adds 「すぎる」 to become 「うるさすぎる」, too loud, with the negative tone of exceeding the appropriate level and being unbearable. 「その音楽は」 marks the topic with 「は」. 「うるさい」 basically means noisy, loud. The whole sentence means that music is way too loud.","grammar:1467:ex:words:0:zh":"that","grammar:1467:ex:words:0:pos":"pre-noun adjectival","grammar:1467:ex:words:1:zh":"music","grammar:1467:ex:words:1:note":"おんがく","grammar:1467:ex:words:1:pos":"noun","grammar:1467:ex:words:2:zh":"(topic)","grammar:1467:ex:words:2:pos":"particle","grammar:1467:ex:words:3:zh":"too loud","grammar:1467:ex:words:3:pos":"adjective","grammar:1467:ex:points:0":"❗〜すぎる: too much … (うるさい→うるさすぎる).","grammar:1467:ex:points:1":"うるさい: noisy, loud.","grammar:1467:ex2:trans":"There's a very noisy neighbor.","grammar:1467:ex2:structure":"うるさい〜がいる","grammar:1467:ex2:words:0:zh":"noisy","grammar:1467:ex2:words:0:pos":"adjective","grammar:1467:ex2:words:1:zh":"neighbor","grammar:1467:ex2:words:1:note":"りんじん","grammar:1467:ex2:words:1:pos":"noun","grammar:1467:ex2:words:2:zh":"(nominative)","grammar:1467:ex2:words:2:pos":"particle","grammar:1467:ex2:words:3:zh":"there is / are","grammar:1467:ex2:words:3:pos":"verb","grammar:1467:ex2:points:0":"うるさい隣人: a noisy neighbor.","grammar:1467:ex2:points:1":"隣人 (りんじん): neighbor.","grammar:1467:ex3:trans":"He's noisy, so I can't concentrate.","grammar:1467:ex3:structure":"〜くて〜できない","grammar:1467:ex3:words:0:zh":"he","grammar:1467:ex3:words:0:note":"かれ","grammar:1467:ex3:words:0:pos":"pronoun","grammar:1467:ex3:words:1:zh":"(topic)","grammar:1467:ex3:words:1:pos":"particle","grammar:1467:ex3:words:2:zh":"noisy","grammar:1467:ex3:words:2:pos":"adjective","grammar:1467:ex3:words:3:zh":"can't concentrate","grammar:1467:ex3:words:3:note":"しゅうちゅうできない","grammar:1467:ex3:words:3:pos":"verb","grammar:1467:ex3:points:0":"❗〜くて: because … (the adjective te-form shows cause and effect).","grammar:1467:ex3:points:1":"集中できない: can't concentrate.","grammar:1467:ex4:trans":"Please don't be noisy.","grammar:1467:ex4:structure":"うるさくしないでください","grammar:1467:ex4:words:0:zh":"noisily","grammar:1467:ex4:words:0:pos":"adverb","grammar:1467:ex4:words:1:zh":"don't do (it)","grammar:1467:ex4:words:1:pos":"verb","grammar:1467:ex4:words:2:zh":"please","grammar:1467:ex4:words:2:pos":"auxiliary verb","grammar:1467:ex4:points:0":"❗うるさくする: to be noisy (うるさい→うるさく＋する).","grammar:1467:ex4:points:1":"「〜ないでください」: please don't …","grammar:1467:ex5:trans":"This place is quiet and not noisy.","grammar:1467:ex5:structure":"〜は〜でうるさくない","grammar:1467:ex5:words:0:zh":"this","grammar:1467:ex5:words:0:pos":"pre-noun adjectival","grammar:1467:ex5:words:1:zh":"place","grammar:1467:ex5:words:1:note":"ばしょ","grammar:1467:ex5:words:1:pos":"noun","grammar:1467:ex5:words:2:zh":"(topic)","grammar:1467:ex5:words:2:pos":"particle","grammar:1467:ex5:words:3:zh":"quiet","grammar:1467:ex5:words:3:note":"しずか","grammar:1467:ex5:words:3:pos":"na-adjective","grammar:1467:ex5:words:4:zh":"(te-form)","grammar:1467:ex5:words:4:pos":"auxiliary verb","grammar:1467:ex5:words:5:zh":"not noisy","grammar:1467:ex5:words:5:pos":"adjective","grammar:1467:ex5:points:0":"❗〜で: (na-adjective linking) … and ….","grammar:1467:ex5:points:1":"うるさくない: not noisy."},"1468":{"example:1468:exzh":"That article is really interesting.","example:1468:exzh2":"I read newspaper articles every day.","example:1468:exzh3":"A new article has been published.","example:1468:exzh4":"He's a journalist who writes articles.","example:1468:exzh5":"Please check the content of the article."},"1469":{"example:1469:exzh":"He's my colleague.","example:1469:exzh2":"I had lunch together with a colleague.","example:1469:exzh3":"There are many colleagues at this company.","example:1469:exzh4":"I'm moving a project forward with a colleague.","example:1469:exzh5":"She's a colleague you can trust."},"1470":{"example:1470:exzh":"This land is very fertile.","example:1470:exzh2":"I plan to buy land.","example:1470:exzh3":"Land prices are rising.","example:1470:exzh4":"That land has a lot of history.","example:1470:exzh5":"He's involved in land development."},"1471":{"example:1471:exzh":"Tomorrow it might rain, or it might be sunny.","example:1471:exzh2":"It's a choice of A or B.","example:1471:exzh3":"He's either a doctor, or possibly a teacher as well.","example:1471:exzh4":"Morning or afternoon works for the time.","example:1471:exzh5":"I'd like to hear your opinion or suggestion."},"1472":{"example:1472:exzh":"I have to tidy up my room.","example:1472:exzh2":"He's good at tidying up.","example:1472:exzh3":"Tidying up takes time.","example:1472:exzh4":"Let's take a rest once the tidying up is done.","example:1472:exzh5":"Could you give me a hand with the tidying up today?"},"1473":{"example:1473:exzh":"I opened a new account.","example:1473:exzh2":"There's no money in that account.","example:1473:exzh3":"Please check the account balance.","example:1473:exzh4":"He has several accounts.","example:1473:exzh5":"This account is convenient."},"1474":{"example:1474:exzh":"We need to talk it over to clear up this misunderstanding.","example:1474:exzh2":"It's my fault that the misunderstanding happened.","example:1474:exzh3":"I'm glad the misunderstanding with him is cleared up.","example:1474:exzh4":"Let's be careful so we don't cause any misunderstandings.","example:1474:exzh5":"She said she wants the misunderstanding cleared up."},"1476":{"example:1476:exzh":"He's someone with a strong sense of justice.","example:1476:exzh2":"Fight to defend justice.","example:1476:exzh3":"Justice can be harsh at times.","example:1476:exzh4":"She's active in the cause of justice.","example:1476:exzh5":"I want to be an ally of justice."},"1477":{"example:1477:exzh":"A problem came up internally.","example:1477:exzh2":"Can you access internal information?","example:1477:exzh3":"We need to look into the internal structure.","example:1477:exzh4":"The inside of the company is very complicated.","example:1477:exzh5":"The internal team is working together."},"1478":{"example:1478:exzh":"Please give a good example.","example:1478:exzh2":"That example is easy to understand.","example:1478:exzh3":"We need some examples.","example:1478:exzh4":"There are many examples of this.","example:1478:exzh5":"He is a good example."},"1479":{"example:1479:exzh":"I'm excited about the match.","example:1479:exzh2":"He got excited and shouted.","example:1479:exzh3":"When I get excited, my hands shake.","example:1479:exzh4":"I'm excited about the new game.","example:1479:exzh5":"I can't hold back my excitement."},"1480":{"example:1480:exzh":"Please always turn off the lights.","example:1480:exzh2":"The light in this room is dim.","example:1480:exzh3":"The electricity bill has gotten a lot higher.","example:1480:exzh4":"You must not use more electricity.","example:1480:exzh5":"Life without electricity is inconvenient.","grammar:1480:ex:trans":"Please always turn off the light.","grammar:1480:ex:structure":"〜を消してください","grammar:1480:ex:explain":"This is a request sentence, 「〜を消してください」. 「を」 marks the object 「電気」 (electricity, the light), and the verb 「消す」 means to switch off or put out; its te-form 「消して」 plus 「ください」 means please turn it off. 「電気を消す」 is the set phrase for \"turn off the light\"; the opposite, \"turn on the light,\" is 「電気をつける」. 「いつも」 is an adverb = always, at all times. The whole sentence means \"Please always turn off the light,\" in a polite tone.","grammar:1480:ex:words:0:zh":"always, at all times","grammar:1480:ex:words:0:pos":"adverb","grammar:1480:ex:words:1:zh":"light (electric light)","grammar:1480:ex:words:1:note":"でんき","grammar:1480:ex:words:1:pos":"noun","grammar:1480:ex:words:2:zh":"(object marker)","grammar:1480:ex:words:2:pos":"particle","grammar:1480:ex:words:3:zh":"turn off","grammar:1480:ex:words:3:note":"けして","grammar:1480:ex:words:3:pos":"verb","grammar:1480:ex:words:4:zh":"please","grammar:1480:ex:words:4:pos":"auxiliary verb","grammar:1480:ex:points:0":"❗電気（でんき）: electricity, light; 電気を消す = turn off the light (消す = switch off).","grammar:1480:ex:points:1":"電気を消す: turn off the light.","grammar:1480:ex2:trans":"The lighting in this room is dim.","grammar:1480:ex2:structure":"(better as 部屋が暗い)","grammar:1480:ex2:words:0:zh":"this","grammar:1480:ex2:words:0:pos":"pre-noun adjectival","grammar:1480:ex2:words:1:zh":"room","grammar:1480:ex2:words:1:note":"へや","grammar:1480:ex2:words:1:pos":"noun","grammar:1480:ex2:words:2:zh":"(topic)","grammar:1480:ex2:words:2:pos":"particle","grammar:1480:ex2:words:3:zh":"light","grammar:1480:ex2:words:3:note":"でんき","grammar:1480:ex2:words:3:pos":"noun","grammar:1480:ex2:words:4:zh":"(nominative)","grammar:1480:ex2:words:4:pos":"particle","grammar:1480:ex2:words:5:zh":"dark","grammar:1480:ex2:words:5:note":"くらい","grammar:1480:ex2:words:5:pos":"adjective","grammar:1480:ex2:words:6:zh":"(polite form)","grammar:1480:ex2:words:6:pos":"copula","grammar:1480:ex2:points:0":"❗This sentence is better as 「部屋が暗い」; 電気 = light / lighting.","grammar:1480:ex2:points:1":"電気: light.","grammar:1480:ex3:trans":"The electricity bill has gone up a lot.","grammar:1480:ex3:structure":"〜が高くなった","grammar:1480:ex3:words:0:zh":"electricity bill","grammar:1480:ex3:words:0:note":"でんきだい","grammar:1480:ex3:words:0:pos":"noun","grammar:1480:ex3:words:1:zh":"(nominative)","grammar:1480:ex3:words:1:pos":"particle","grammar:1480:ex3:words:2:zh":"has gotten higher","grammar:1480:ex3:words:2:note":"たかくなった","grammar:1480:ex3:words:2:pos":"verb","grammar:1480:ex3:points:0":"❗電気代: electricity bill (電気 + 代); 〜くなる = become….","grammar:1480:ex3:points:1":"電気代: electricity bill.","grammar:1480:ex4:trans":"You must not use more electricity.","grammar:1480:ex4:structure":"〜を使ってはいけません","grammar:1480:ex4:words:0:zh":"electricity","grammar:1480:ex4:words:0:note":"でんき","grammar:1480:ex4:words:0:pos":"noun","grammar:1480:ex4:words:1:zh":"(object marker)","grammar:1480:ex4:words:1:pos":"particle","grammar:1480:ex4:words:2:zh":"more","grammar:1480:ex4:words:2:pos":"adverb","grammar:1480:ex4:words:3:zh":"use","grammar:1480:ex4:words:3:note":"つかって","grammar:1480:ex4:words:3:pos":"verb","grammar:1480:ex4:words:4:zh":"(emphasis)","grammar:1480:ex4:words:4:pos":"particle","grammar:1480:ex4:words:5:zh":"must not","grammar:1480:ex4:words:5:pos":"set phrase","grammar:1480:ex4:points:0":"❗〜てはいけません: you must not…; 電気を使う = use electricity.","grammar:1480:ex4:points:1":"電気を使う: use electricity.","grammar:1480:ex5:trans":"Life without electricity is inconvenient.","grammar:1480:ex5:structure":"〜のない生活は不便です","grammar:1480:ex5:words:0:zh":"electricity","grammar:1480:ex5:words:0:note":"でんき","grammar:1480:ex5:words:0:pos":"noun","grammar:1480:ex5:words:1:zh":"'s","grammar:1480:ex5:words:1:pos":"particle","grammar:1480:ex5:words:2:zh":"don't have","grammar:1480:ex5:words:2:pos":"adjective","grammar:1480:ex5:words:3:zh":"life","grammar:1480:ex5:words:3:note":"せいかつ","grammar:1480:ex5:words:3:pos":"noun","grammar:1480:ex5:words:4:zh":"(topic)","grammar:1480:ex5:words:4:pos":"particle","grammar:1480:ex5:words:5:zh":"inconvenient","grammar:1480:ex5:words:5:note":"ふべん","grammar:1480:ex5:words:5:pos":"na-adjective","grammar:1480:ex5:words:6:zh":"(polite form)","grammar:1480:ex5:words:6:pos":"copula","grammar:1480:ex5:points:0":"❗電気のない: without electricity (a negated pre-noun modifier); 不便 = inconvenient.","grammar:1480:ex5:points:1":"電気のない生活: life without electricity.","exam:1480:zh":"The room is dark, so please press the switch and turn on the light.","exam:1480:why":"「電気をつける」 here means to turn on the light, which fits the scene of pressing a switch to brighten the room. 「火をつける」 means to light a fire, not to turn on a light here."},"1481":{"example:1481:exzh":"I practice Japanese every day.","example:1481:exzh2":"Practicing the piano is necessary.","example:1481:exzh3":"With repeated practice, you'll get better.","example:1481:exzh4":"He is practicing soccer.","example:1481:exzh5":"Let's practice for the exam.","grammar:1481:ex:trans":"I practice Japanese every day.","grammar:1481:ex:structure":"〜の練習をしています","grammar:1481:ex:explain":"This sentence uses 「〜の練習をする」 to say that you practice something. 「練習」 is a noun, and 「〜をする」 turns it into an action. 「日本語の」 is joined with 「の」: 「日本語の練習」 = practice of Japanese. 「しています」 uses 「〜ている」 to show an ongoing or habitual action. 「毎日」 is an adverb = every day. The whole sentence 「毎日日本語の練習をしています」 means \"I practice Japanese every day,\" emphasizing a regular habit.","grammar:1481:ex:words:0:zh":"every day","grammar:1481:ex:words:0:note":"まいにち","grammar:1481:ex:words:0:pos":"adverb","grammar:1481:ex:words:1:zh":"Japanese","grammar:1481:ex:words:1:note":"にほんご","grammar:1481:ex:words:1:pos":"noun","grammar:1481:ex:words:2:zh":"'s","grammar:1481:ex:words:2:pos":"particle","grammar:1481:ex:words:3:zh":"practice","grammar:1481:ex:words:3:note":"れんしゅう","grammar:1481:ex:words:3:pos":"noun","grammar:1481:ex:words:4:zh":"(object marker)","grammar:1481:ex:words:4:pos":"particle","grammar:1481:ex:words:5:zh":"is doing","grammar:1481:ex:words:5:pos":"verb","grammar:1481:ex:points:0":"❗練習（れんしゅう）: practice; 練習をする = practice.","grammar:1481:ex:points:1":"日本語の練習: Japanese practice.","grammar:1481:ex2:trans":"Piano practice is necessary.","grammar:1481:ex2:structure":"〜の練習が必要です","grammar:1481:ex2:words:0:zh":"piano","grammar:1481:ex2:words:0:note":"loanword","grammar:1481:ex2:words:0:pos":"noun","grammar:1481:ex2:words:1:zh":"'s","grammar:1481:ex2:words:1:pos":"particle","grammar:1481:ex2:words:2:zh":"practice","grammar:1481:ex2:words:2:note":"れんしゅう","grammar:1481:ex2:words:2:pos":"noun","grammar:1481:ex2:words:3:zh":"(nominative)","grammar:1481:ex2:words:3:pos":"particle","grammar:1481:ex2:words:4:zh":"necessary","grammar:1481:ex2:words:4:note":"ひつよう","grammar:1481:ex2:words:4:pos":"na-adjective","grammar:1481:ex2:words:5:zh":"(polite form)","grammar:1481:ex2:words:5:pos":"copula","grammar:1481:ex2:points:0":"❗ピアノ: piano; 練習が必要 = practice is needed.","grammar:1481:ex2:points:1":"ピアノの練習: piano practice.","grammar:1481:ex3:trans":"With repeated practice, you'll get better.","grammar:1481:ex3:structure":"〜を重ねて〜になります","grammar:1481:ex3:words:0:zh":"practice","grammar:1481:ex3:words:0:note":"れんしゅう","grammar:1481:ex3:words:0:pos":"noun","grammar:1481:ex3:words:1:zh":"(object marker)","grammar:1481:ex3:words:1:pos":"particle","grammar:1481:ex3:words:2:zh":"repeatedly","grammar:1481:ex3:words:2:note":"かさねて","grammar:1481:ex3:words:2:pos":"verb","grammar:1481:ex3:words:3:zh":"good at","grammar:1481:ex3:words:3:note":"じょうず","grammar:1481:ex3:words:3:pos":"na-adjective","grammar:1481:ex3:words:4:zh":"(result)","grammar:1481:ex3:words:4:pos":"particle","grammar:1481:ex3:words:5:zh":"become","grammar:1481:ex3:words:5:pos":"verb","grammar:1481:ex3:points:0":"❗練習を重ねる: practice over and over (重ねる = pile up); 上手になる = get better.","grammar:1481:ex3:points:1":"練習を重ねる: practice diligently.","grammar:1481:ex4:trans":"He is practicing soccer.","grammar:1481:ex4:structure":"〜の練習をしています","grammar:1481:ex4:words:0:zh":"he","grammar:1481:ex4:words:0:note":"かれ","grammar:1481:ex4:words:0:pos":"pronoun","grammar:1481:ex4:words:1:zh":"(topic)","grammar:1481:ex4:words:1:pos":"particle","grammar:1481:ex4:words:2:zh":"soccer","grammar:1481:ex4:words:2:note":"loanword","grammar:1481:ex4:words:2:pos":"noun","grammar:1481:ex4:words:3:zh":"'s","grammar:1481:ex4:words:3:pos":"particle","grammar:1481:ex4:words:4:zh":"practice","grammar:1481:ex4:words:4:note":"れんしゅう","grammar:1481:ex4:words:4:pos":"noun","grammar:1481:ex4:words:5:zh":"(object marker)","grammar:1481:ex4:words:5:pos":"particle","grammar:1481:ex4:words:6:zh":"is doing","grammar:1481:ex4:words:6:pos":"verb","grammar:1481:ex4:points:0":"サッカーの練習: soccer practice.","grammar:1481:ex4:points:1":"練習をする: practice.","grammar:1481:ex5:trans":"Let's practice for the exam.","grammar:1481:ex5:structure":"〜に向けて練習をしましょう","grammar:1481:ex5:words:0:zh":"test","grammar:1481:ex5:words:0:note":"しけん","grammar:1481:ex5:words:0:pos":"noun","grammar:1481:ex5:words:1:zh":"(direction)","grammar:1481:ex5:words:1:pos":"particle","grammar:1481:ex5:words:2:zh":"heading toward","grammar:1481:ex5:words:2:note":"むけて","grammar:1481:ex5:words:2:pos":"set phrase","grammar:1481:ex5:words:3:zh":"practice","grammar:1481:ex5:words:3:note":"れんしゅう","grammar:1481:ex5:words:3:pos":"noun","grammar:1481:ex5:words:4:zh":"(object marker)","grammar:1481:ex5:words:4:pos":"particle","grammar:1481:ex5:words:5:zh":"let's do","grammar:1481:ex5:words:5:pos":"verb","grammar:1481:ex5:points:0":"❗〜に向けて: toward…, in preparation for…; 試験に向けて = for the exam.","grammar:1481:ex5:points:1":"〜ましょう: a suggestion.","exam:1481:zh":"I want to get good at piano, so I practice the same piece every day.","exam:1481:why":"Playing a piece over and over to improve your playing is 「練習」. 「散歩」 means a walk, and it can't pair with 同じ曲の to mean playing practice."},"1482":{"example:1482:exzh":"I made a new table.","example:1482:exzh2":"Please look at this table.","example:1482:exzh3":"Please write the numbers in this table.","example:1482:exzh4":"Let's check the data in the table.","example:1482:exzh5":"This table contains important information."},"1483":{"example:1483:exzh":"Contact with other people is important.","example:1483:exzh2":"Viruses can sometimes spread through contact.","example:1483:exzh3":"The ground here is slippery, so please be careful about contact.","example:1483:exzh4":"He is avoiding contact with other people.","example:1483:exzh5":"Let's be careful about contact infections."},"1484":{"example:1484:exzh":"We will let you know about changes to the plan.","example:1484:exzh2":"I changed my address.","example:1484:exzh3":"Please let us know if a change is needed.","example:1484:exzh4":"Please tell me the details of this change.","example:1484:exzh5":"The change procedure is simple."},"1485":{"example:1485:exzh":"We are in the same group.","example:1485:exzh2":"I will take part in the group activity.","example:1485:exzh3":"This group is interesting.","example:1485:exzh4":"A new member joined the group.","example:1485:exzh5":"Let's exchange opinions in the group.","grammar:1485:ex:trans":"We are in the same group.","grammar:1485:ex:structure":"〜は同じ〜です","grammar:1485:ex:explain":"This is a noun predicate sentence, 「〜は同じ〜です」. 「私たちは」 uses 「は」 to mark the topic; 「同じ」 is a pre-noun adjectival that directly modifies the noun 「グループ」: 「同じグループ」 = the same group. Note that 「同じ」 is special — it doesn't take 「な」 or 「の」 when modifying a noun. 「グループ」 is a loanword (group). The final 「です」 states the judgment. The whole sentence means \"We're in the same group.\"","grammar:1485:ex:words:0:zh":"we","grammar:1485:ex:words:0:note":"わたしたち","grammar:1485:ex:words:0:pos":"pronoun","grammar:1485:ex:words:1:zh":"(topic)","grammar:1485:ex:words:1:pos":"particle","grammar:1485:ex:words:2:zh":"same","grammar:1485:ex:words:2:note":"おなじ","grammar:1485:ex:words:2:pos":"pre-noun adjectival","grammar:1485:ex:words:3:zh":"group","grammar:1485:ex:words:3:note":"loanword","grammar:1485:ex:words:3:pos":"noun","grammar:1485:ex:words:4:zh":"is","grammar:1485:ex:words:4:pos":"copula","grammar:1485:ex:points:0":"❗グループ: group, team (group); 同じ = the same.","grammar:1485:ex:points:1":"同じグループ: the same group.","grammar:1485:ex2:trans":"I'll take part in the group activity.","grammar:1485:ex2:structure":"〜に参加します","grammar:1485:ex2:words:0:zh":"group","grammar:1485:ex2:words:0:note":"loanword","grammar:1485:ex2:words:0:pos":"noun","grammar:1485:ex2:words:1:zh":"event","grammar:1485:ex2:words:1:note":"かつどう","grammar:1485:ex2:words:1:pos":"noun","grammar:1485:ex2:words:2:zh":"(object)","grammar:1485:ex2:words:2:pos":"particle","grammar:1485:ex2:words:3:zh":"join","grammar:1485:ex2:words:3:note":"さんかします","grammar:1485:ex2:words:3:pos":"verb","grammar:1485:ex2:points:0":"❗グループ活動: group activity; 〜に参加する = take part in….","grammar:1485:ex2:points:1":"活動に参加: take part in an activity.","grammar:1485:ex3:trans":"This group is interesting.","grammar:1485:ex3:structure":"〜は面白いです","grammar:1485:ex3:words:0:zh":"this","grammar:1485:ex3:words:0:pos":"pre-noun adjectival","grammar:1485:ex3:words:1:zh":"group","grammar:1485:ex3:words:1:note":"loanword","grammar:1485:ex3:words:1:pos":"noun","grammar:1485:ex3:words:2:zh":"(topic)","grammar:1485:ex3:words:2:pos":"particle","grammar:1485:ex3:words:3:zh":"interesting","grammar:1485:ex3:words:3:note":"おもしろい","grammar:1485:ex3:words:3:pos":"adjective","grammar:1485:ex3:words:4:zh":"(polite form)","grammar:1485:ex3:words:4:pos":"copula","grammar:1485:ex3:points:0":"このグループ: this group.","grammar:1485:ex3:points:1":"面白い: interesting, fun.","grammar:1485:ex4:trans":"A new member joined the group.","grammar:1485:ex4:structure":"〜に加わりました","grammar:1485:ex4:words:0:zh":"new","grammar:1485:ex4:words:0:note":"あたらしい","grammar:1485:ex4:words:0:pos":"adjective","grammar:1485:ex4:words:1:zh":"member","grammar:1485:ex4:words:1:note":"loanword","grammar:1485:ex4:words:1:pos":"noun","grammar:1485:ex4:words:2:zh":"(nominative)","grammar:1485:ex4:words:2:pos":"particle","grammar:1485:ex4:words:3:zh":"group","grammar:1485:ex4:words:3:note":"loanword","grammar:1485:ex4:words:3:pos":"noun","grammar:1485:ex4:words:4:zh":"(result)","grammar:1485:ex4:words:4:pos":"particle","grammar:1485:ex4:words:5:zh":"joined","grammar:1485:ex4:words:5:note":"くわわりました","grammar:1485:ex4:words:5:pos":"verb","grammar:1485:ex4:points:0":"❗〜に加わる: join… (加わる is an intransitive verb); メンバー = member.","grammar:1485:ex4:points:1":"グループに加わる: join a group.","grammar:1485:ex5:trans":"Let's exchange opinions in the group.","grammar:1485:ex5:structure":"〜で〜を交換しましょう","grammar:1485:ex5:words:0:zh":"group","grammar:1485:ex5:words:0:note":"loanword","grammar:1485:ex5:words:0:pos":"noun","grammar:1485:ex5:words:1:zh":"(scope)","grammar:1485:ex5:words:1:pos":"particle","grammar:1485:ex5:words:2:zh":"opinion","grammar:1485:ex5:words:2:note":"いけん","grammar:1485:ex5:words:2:pos":"noun","grammar:1485:ex5:words:3:zh":"(object marker)","grammar:1485:ex5:words:3:pos":"particle","grammar:1485:ex5:words:4:zh":"let's exchange","grammar:1485:ex5:words:4:note":"こうかんしましょう","grammar:1485:ex5:words:4:pos":"verb","grammar:1485:ex5:points:0":"❗意見を交換する: exchange opinions; ❓グループで = in the group (で marks the scope).","grammar:1485:ex5:points:1":"意見を交換: exchange opinions."},"1486":{"example:1486:exzh":"The price of this product is high.","example:1486:exzh2":"The value increased.","example:1486:exzh3":"Please calculate the value.","example:1486:exzh4":"This value is special.","example:1486:exzh5":"I will enter the new value."},"1487":{"example:1487:exzh":"That's a good idea.","grammar:1487:ex:trans":"This is a good idea.","grammar:1487:ex:structure":"これは、〔良いアイデア〕＋です. 「良い（よい）」 = good (casual speech usually says いい).","grammar:1487:ex:explain":"This is a noun predicate sentence, and the key is how 「良い」 conjugates. 「良い」 is read よい, and in casual speech 「いい」 is more common, but note: once it has to inflect (past, negative, etc.) you have to go back to the stem よい — for example, the past form is 「良かった（よかった）」, and 「いかった」 is wrong. Here 「良いアイデア」 = a good idea, modifying the noun directly. The whole sentence 「これは良いアイデアです」 means 'This is a good idea.'","grammar:1487:ex:words:0:zh":"this","grammar:1487:ex:words:0:pos":"pronoun","grammar:1487:ex:words:1:zh":"(topic marker)","grammar:1487:ex:words:1:pos":"particle","grammar:1487:ex:words:2:zh":"good","grammar:1487:ex:words:2:note":"よい","grammar:1487:ex:words:2:pos":"adjective","grammar:1487:ex:words:3:zh":"idea","grammar:1487:ex:words:3:note":"loanword","grammar:1487:ex:words:3:pos":"noun","grammar:1487:ex:words:4:zh":"is","grammar:1487:ex:words:4:pos":"copula","grammar:1487:ex:points:0":"良い（よい）: good (casual speech mostly uses 「いい」, but inflections use よい／良かった)","grammar:1487:ex:points:1":"良いアイデア: a good idea"},"1488":{"example:1488:exzh":"If I'm happy with the service, I'll pay a tip."},"1490":{"example:1490:exzh":"We received feedback from a customer."},"1491":{"example:1491:exzh":"The park is two blocks ahead."},"1493":{"example:1493:exzh":"He received a prestigious award."},"1494":{"example:1494:exzh":"He has the role of guiding people."},"1495":{"example:1495:exzh":"He works at a factory.","example:1495:exzh2":"This factory uses new technology.","example:1495:exzh3":"Touring the factory is very interesting.","example:1495:exzh4":"Safety management at the factory is important.","example:1495:exzh5":"She is helping with running the factory.","grammar:1495:ex:trans":"He works at a factory.","grammar:1495:ex:structure":"〜で働いています","grammar:1495:ex:explain":"The key point here is that the workplace takes 「で」. The 「で」 in 「工場で」 marks where the action takes place = at the factory. 「働いている」 uses 「〜ている」 to show a continuing state — currently doing this job — rather than a single moment of working. Be careful to distinguish 「で」 (where an action happens) from 「に」 (where something exists): the action of working takes place at the factory, so 「で」 is used. The whole sentence means \"He works at a factory.\"","grammar:1495:ex:words:0:zh":"he","grammar:1495:ex:words:0:note":"かれ","grammar:1495:ex:words:0:pos":"pronoun","grammar:1495:ex:words:1:zh":"(topic)","grammar:1495:ex:words:1:pos":"particle","grammar:1495:ex:words:2:zh":"factory","grammar:1495:ex:words:2:note":"こうじょう","grammar:1495:ex:words:2:pos":"noun","grammar:1495:ex:words:3:zh":"(place)","grammar:1495:ex:words:3:pos":"particle","grammar:1495:ex:words:4:zh":"is working","grammar:1495:ex:words:4:note":"はたらいています","grammar:1495:ex:words:4:pos":"verb","grammar:1495:ex:points:0":"❗工場（こうじょう）: factory; ❓工場で = at the factory (で marks the place).","grammar:1495:ex:points:1":"工場で働く: work at a factory.","grammar:1495:ex2:trans":"This factory uses new technology.","grammar:1495:ex2:structure":"〜を使っています","grammar:1495:ex2:words:0:zh":"this","grammar:1495:ex2:words:0:pos":"pre-noun adjectival","grammar:1495:ex2:words:1:zh":"factory","grammar:1495:ex2:words:1:note":"こうじょう","grammar:1495:ex2:words:1:pos":"noun","grammar:1495:ex2:words:2:zh":"(topic)","grammar:1495:ex2:words:2:pos":"particle","grammar:1495:ex2:words:3:zh":"new","grammar:1495:ex2:words:3:note":"あたらしい","grammar:1495:ex2:words:3:pos":"adjective","grammar:1495:ex2:words:4:zh":"technology","grammar:1495:ex2:words:4:note":"ぎじゅつ","grammar:1495:ex2:words:4:pos":"noun","grammar:1495:ex2:words:5:zh":"(object marker)","grammar:1495:ex2:words:5:pos":"particle","grammar:1495:ex2:words:6:zh":"are using","grammar:1495:ex2:words:6:note":"つかっています","grammar:1495:ex2:words:6:pos":"verb","grammar:1495:ex2:points:0":"新しい技術: new technology.","grammar:1495:ex2:points:1":"使う: use.","grammar:1495:ex3:trans":"Touring the factory is very interesting.","grammar:1495:ex3:structure":"〜の見学は面白いです","grammar:1495:ex3:words:0:zh":"factory","grammar:1495:ex3:words:0:note":"こうじょう","grammar:1495:ex3:words:0:pos":"noun","grammar:1495:ex3:words:1:zh":"'s","grammar:1495:ex3:words:1:pos":"particle","grammar:1495:ex3:words:2:zh":"tour","grammar:1495:ex3:words:2:note":"けんがく","grammar:1495:ex3:words:2:pos":"noun","grammar:1495:ex3:words:3:zh":"(topic)","grammar:1495:ex3:words:3:pos":"particle","grammar:1495:ex3:words:4:zh":"extremely","grammar:1495:ex3:words:4:pos":"adverb","grammar:1495:ex3:words:5:zh":"interesting","grammar:1495:ex3:words:5:note":"おもしろい","grammar:1495:ex3:words:5:pos":"adjective","grammar:1495:ex3:words:6:zh":"(polite form)","grammar:1495:ex3:words:6:pos":"copula","grammar:1495:ex3:points:0":"❗見学: a study visit (見 + 学); 工場の見学 = touring a factory.","grammar:1495:ex3:points:1":"見学: a study visit.","grammar:1495:ex4:trans":"Safety management at the factory is important.","grammar:1495:ex4:structure":"〜の安全管理が重要です","grammar:1495:ex4:words:0:zh":"factory","grammar:1495:ex4:words:0:note":"こうじょう","grammar:1495:ex4:words:0:pos":"noun","grammar:1495:ex4:words:1:zh":"'s","grammar:1495:ex4:words:1:pos":"particle","grammar:1495:ex4:words:2:zh":"safety management","grammar:1495:ex4:words:2:note":"あんぜんかんり","grammar:1495:ex4:words:2:pos":"noun","grammar:1495:ex4:words:3:zh":"(nominative)","grammar:1495:ex4:words:3:pos":"particle","grammar:1495:ex4:words:4:zh":"important","grammar:1495:ex4:words:4:note":"じゅうよう","grammar:1495:ex4:words:4:pos":"na-adjective","grammar:1495:ex4:words:5:zh":"(polite form)","grammar:1495:ex4:words:5:pos":"copula","grammar:1495:ex4:points:0":"❗安全管理: safety management; 工場の安全管理 = factory safety.","grammar:1495:ex4:points:1":"安全管理: safety management.","grammar:1495:ex5:trans":"She is helping run the factory.","grammar:1495:ex5:structure":"〜の運営を手伝っています","grammar:1495:ex5:words:0:zh":"she","grammar:1495:ex5:words:0:note":"かのじょ","grammar:1495:ex5:words:0:pos":"pronoun","grammar:1495:ex5:words:1:zh":"(topic)","grammar:1495:ex5:words:1:pos":"particle","grammar:1495:ex5:words:2:zh":"factory","grammar:1495:ex5:words:2:note":"こうじょう","grammar:1495:ex5:words:2:pos":"noun","grammar:1495:ex5:words:3:zh":"'s","grammar:1495:ex5:words:3:pos":"particle","grammar:1495:ex5:words:4:zh":"management","grammar:1495:ex5:words:4:note":"うんえい","grammar:1495:ex5:words:4:pos":"noun","grammar:1495:ex5:words:5:zh":"(object marker)","grammar:1495:ex5:words:5:pos":"particle","grammar:1495:ex5:words:6:zh":"is helping","grammar:1495:ex5:words:6:note":"てつだっています","grammar:1495:ex5:words:6:pos":"verb","grammar:1495:ex5:points:0":"❗運営: management, operation; 工場の運営 = running the factory.","grammar:1495:ex5:points:1":"運営を手伝う: to help run something."},"1496":{"example:1496:exzh":"There's a soccer match today.","example:1496:exzh2":"He won the match.","example:1496:exzh3":"I like watching matches.","example:1496:exzh4":"I practice before the match.","example:1496:exzh5":"This match is very difficult.","grammar:1496:ex:trans":"There's a soccer game today.","grammar:1496:ex:structure":"〜の試合が〜あります","grammar:1496:ex:explain":"This is a variant of the existential pattern 「〜がある」, used to say that an event will take place. In 「サッカーの試合」, 「の」 links the two parts, meaning a soccer game; 「が」 marks the subject, and 「あります」 means that (the event) exists, there is. 「今日」 is a time word and goes directly before the verb. 「試合（しあい）」 means game, match. So the whole sentence 「サッカーの試合が今日あります」 means there is a soccer game today, in a polite tone, used to announce an event.","grammar:1496:ex:words:0:zh":"soccer","grammar:1496:ex:words:0:note":"loanword","grammar:1496:ex:words:0:pos":"noun","grammar:1496:ex:words:1:zh":"'s","grammar:1496:ex:words:1:pos":"particle","grammar:1496:ex:words:2:zh":"competition","grammar:1496:ex:words:2:note":"しあい","grammar:1496:ex:words:2:pos":"noun","grammar:1496:ex:words:3:zh":"(nominative)","grammar:1496:ex:words:3:pos":"particle","grammar:1496:ex:words:4:zh":"today","grammar:1496:ex:words:4:note":"きょう","grammar:1496:ex:words:4:pos":"noun","grammar:1496:ex:words:5:zh":"there is / are","grammar:1496:ex:words:5:pos":"verb","grammar:1496:ex:points:0":"❗試合（しあい）: game, match; サッカーの試合 = soccer game.","grammar:1496:ex:points:1":"試合がある: there is a game.","grammar:1496:ex2:trans":"He won the game.","grammar:1496:ex2:structure":"〜に勝ちました","grammar:1496:ex2:words:0:zh":"he","grammar:1496:ex2:words:0:note":"かれ","grammar:1496:ex2:words:0:pos":"pronoun","grammar:1496:ex2:words:1:zh":"(topic)","grammar:1496:ex2:words:1:pos":"particle","grammar:1496:ex2:words:2:zh":"competition","grammar:1496:ex2:words:2:note":"しあい","grammar:1496:ex2:words:2:pos":"noun","grammar:1496:ex2:words:3:zh":"(object)","grammar:1496:ex2:words:3:pos":"particle","grammar:1496:ex2:words:4:zh":"won","grammar:1496:ex2:words:4:note":"かちました","grammar:1496:ex2:words:4:pos":"verb","grammar:1496:ex2:points:0":"❗〜に勝つ: to win … (the target takes に); vs 負ける (to lose).","grammar:1496:ex2:points:1":"試合に勝つ: to win a game.","grammar:1496:ex3:trans":"I like watching games.","grammar:1496:ex3:structure":"〜を見るのが好きです","grammar:1496:ex3:words:0:zh":"competition","grammar:1496:ex3:words:0:note":"しあい","grammar:1496:ex3:words:0:pos":"noun","grammar:1496:ex3:words:1:zh":"(object marker)","grammar:1496:ex3:words:1:pos":"particle","grammar:1496:ex3:words:2:zh":"look","grammar:1496:ex3:words:2:note":"みる","grammar:1496:ex3:words:2:pos":"verb","grammar:1496:ex3:words:3:zh":"(nominalizer)","grammar:1496:ex3:words:3:pos":"particle","grammar:1496:ex3:words:4:zh":"(object)","grammar:1496:ex3:words:4:pos":"particle","grammar:1496:ex3:words:5:zh":"to like","grammar:1496:ex3:words:5:note":"すき","grammar:1496:ex3:words:5:pos":"na-adjective","grammar:1496:ex3:words:6:zh":"(polite form)","grammar:1496:ex3:words:6:pos":"copula","grammar:1496:ex3:points:0":"試合を見る: to watch a game.","grammar:1496:ex3:points:1":"〜のが好き: to like doing…","grammar:1496:ex4:trans":"I practice before the game.","grammar:1496:ex4:structure":"〜の前に練習します","grammar:1496:ex4:words:0:zh":"competition","grammar:1496:ex4:words:0:note":"しあい","grammar:1496:ex4:words:0:pos":"noun","grammar:1496:ex4:words:1:zh":"'s","grammar:1496:ex4:words:1:pos":"particle","grammar:1496:ex4:words:2:zh":"before","grammar:1496:ex4:words:2:note":"まえ","grammar:1496:ex4:words:2:pos":"noun","grammar:1496:ex4:words:3:zh":"(point in time)","grammar:1496:ex4:words:3:pos":"particle","grammar:1496:ex4:words:4:zh":"practice","grammar:1496:ex4:words:4:note":"れんしゅうします","grammar:1496:ex4:words:4:pos":"verb","grammar:1496:ex4:points:0":"❗〜の前に: before …; 試合の前 = before the game.","grammar:1496:ex4:points:1":"練習する: to practice.","grammar:1496:ex5:trans":"This game is very difficult.","grammar:1496:ex5:structure":"〜はとても難しいです","grammar:1496:ex5:words:0:zh":"this","grammar:1496:ex5:words:0:pos":"pre-noun adjectival","grammar:1496:ex5:words:1:zh":"competition","grammar:1496:ex5:words:1:note":"しあい","grammar:1496:ex5:words:1:pos":"noun","grammar:1496:ex5:words:2:zh":"(topic)","grammar:1496:ex5:words:2:pos":"particle","grammar:1496:ex5:words:3:zh":"extremely","grammar:1496:ex5:words:3:pos":"adverb","grammar:1496:ex5:words:4:zh":"difficult","grammar:1496:ex5:words:4:note":"むずかしい","grammar:1496:ex5:words:4:pos":"adjective","grammar:1496:ex5:words:5:zh":"(polite form)","grammar:1496:ex5:words:5:pos":"copula","grammar:1496:ex5:points:0":"この試合: this game.","grammar:1496:ex5:points:1":"難しい: difficult."},"1497":{"example:1497:exzh":"Doing self-analysis is important.","example:1497:exzh2":"He is trying to take a fresh look at himself.","example:1497:exzh3":"Self-growth is part of life.","example:1497:exzh4":"Please introduce yourself.","example:1497:exzh5":"Let's try to raise our self-esteem."},"1498":{"example:1498:exzh":"His explanation made sense to me.","example:1498:exzh2":"There are things I just can't accept.","example:1498:exzh3":"We'll discuss it until everyone is satisfied.","example:1498:exzh4":"We need a reason we can accept.","example:1498:exzh5":"It's hard to accept that."},"1499":{"example:1499:exzh":"This story is moving.","example:1499:exzh2":"She likes writing stories.","example:1499:exzh3":"There's a lesson in the story.","example:1499:exzh4":"He knows a famous story.","example:1499:exzh5":"Many characters appear in the story."}};